				background: rgba(68, 85, 234, 0.6);
			}
		}
		&:hover {
			.comment-text {
				span {
					background: rgba(68, 85, 234, 0.65);
				}
			}
		}
	}
}

.tagged-people-row {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 6px;
  flex-wrap: wrap;
}

.tagged-people-row .tag-label {

	font-weight: 600;
}

.targeted-chip {
  display: inline-block;
  font-size: 12px;
  line-height: 1;
  padding: 3px 8px;
  border-radius: 999px;
  background: hsla(0, 0%, 100%, 0.08);
  border: 1px solid hsla(0, 0%, 100%, 0.12);
  color: inherit;
  cursor: default;
}
.targeted-chip:hover {
  background: hsla(0, 0%, 100%, 0.12);
  border-color: hsla(0, 0%, 100%, 0.18);
}


.bubble-tags--block {
  display: flex; 
  margin-top: 6px;
  padding: 0;	
	border-radius: 999px;
	background-color: none;
}

.tagged-summary-chip {
  font-size: 11px;
  line-height: 1;
  padding: 2px 6px;
  border-radius: 999px;
  background: hsla(0,0%,100%,.06);
  border: 1px solid hsla(0,0%,100%,.10);
  box-shadow: 0 1px 1px rgba(0,0,0,.12);
  color: inherit;
  cursor: default;
}
.comment-item.current-user-comment .tagged-summary-chip {
  background: rgba(255,255,255,.10);
  border-color: rgba(255,255,255,.18);
}


.tagged-summary-chip {
  font-size: 11px;
  line-height: 1;
  padding: 2px 6px;
  border-radius: 999px;
  background: hsla(0,0%,100%,.06);
  border: 1px solid hsla(0,0%,100%,.10);
  box-shadow: 0 1px 1px rgba(0,0,0,.12);
}

.comment-item.current-user-comment .tagged-summary-chip {
  background: rgba(255,255,255,.10);
  border-color: rgba(255,255,255,.18);
}

.comment-item { margin-bottom: 2px; }
.sent-by { padding: 3px 3px; }

