(function () {
  // ===========================================================================
  // Slate shims
  // ===========================================================================
  const SF = typeof SlateFunctions !== "undefined" ? SlateFunctions : null;
  const getStateRaw = (k) => (SF?.getState ? SF.getState(k) : undefined);
  const trigger = (n, p) => {
    try { SF?.triggerEvent?.(n, p); } catch {}
  };
  const watch = (k, cb) => (SF?.watch ? SF.watch(k, cb) : () => {});

  // ===========================================================================
  // Config
  // ===========================================================================
  const PAGE_SIZE = 10;

  // Suppress watcher-driven re-render briefly after unread→read to avoid flicker
  const SQUELCH_MS = 700;
  let squelchHydrationUntil = 0; // timestamp (ms)

  // UI smoothing windows (cover optimistic + post-squelch render)
  let suppressBusyUntil = 0;     // timestamp (ms) — skip aria-busy while inside window
  let lockListHeightUntil = 0;   // timestamp (ms) — keep minHeight locked while inside window

  // During squelch, track whether watchers delivered data. If they did,
  // we won't do our manual post-squelch render.
  let touchedDuringSquelch = false;

  // ===========================================================================
  // Utils
  // ===========================================================================
  const parseMaybeJSON = (v) => {
    if (typeof v === "string") {
      const t = v.trim();
      if ((t.startsWith("{") && t.endsWith("}")) || (t.startsWith("[") && t.endsWith("]"))) {
        try { return JSON.parse(t); } catch {}
      }
    }
    return v;
  };

  const fromState = (key) => {
    let v = parseMaybeJSON(getStateRaw(key));
    if (v && typeof v === "object" && Object.prototype.hasOwnProperty.call(v, key)) {
      v = parseMaybeJSON(v[key]);
    }
    return v;
  };

  const asString = (v) => {
    v = parseMaybeJSON(v);
    if (v == null) return "";
    if (typeof v === "string") return v;
    if (typeof v === "number" || typeof v === "boolean") return String(v);
    if (typeof v === "object") {
      if (typeof v.value === "string") return v.value;
      if (Array.isArray(v) && v.length) return String(v[0]);
    }
    return "";
  };

  const escapeHtml = (s) => String(s ?? "")
    .replace(/&/g, "&amp;").replace(/</g, "&lt;")
    .replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");

  const toArray = (v) => {
    v = parseMaybeJSON(v);
    try { if (typeof v === "string") v = JSON.parse(v); } catch {}
    return Array.isArray(v) ? v : (Array.isArray(v?.notifications) ? v.notifications : []);
  };

  const bySentAtDesc = (a, b) =>
    (Date.parse(b?.sentAt || 0) || 0) - (Date.parse(a?.sentAt || 0) || 0);

  const fmtTime = (iso) => {
    const d = new Date(iso);
    return Number.isNaN(+d) ? "" : d.toLocaleString(undefined, {
      weekday: "short", year: "numeric", month: "short", day: "numeric",
      hour: "numeric", minute: "2-digit"
    });
  };

  const getNotificationTypeId = () => {
    const prefix = asString(fromState("v_object_type_prefix"));
    return prefix.endsWith(".") ? `${prefix}notification` : `${prefix}.notification`;
  };

  // ===========================================================================
  // DOM
  // ===========================================================================
  const root = document.querySelector(".w_in_app_notification");
  if (!root) return;

  const listEl = root.querySelector(".nap-list");
  const [tabUnreadBtn, tabReadBtn] = root.querySelectorAll(".nap-tab");
  const actionBtn = root.querySelector(".nap-top .nap-btn");

  const pagEl = root.querySelector(".nap-pag");
  const [prevBtn, pageBtn, nextBtn] =
    pagEl ? pagEl.querySelectorAll("button") : [null, null, null];

  [tabUnreadBtn, tabReadBtn, actionBtn, prevBtn, pageBtn, nextBtn]
    .filter(Boolean)
    .forEach((el) => { try { el.style.cursor = "pointer"; } catch {} });

  // ===========================================================================
  // Smoothing helpers (need DOM refs)
  // ===========================================================================
  const startSmoothingWindow = () => {
    const now = Date.now();
    squelchHydrationUntil = now + SQUELCH_MS;
    suppressBusyUntil     = now + SQUELCH_MS + 80; // cover post-squelch work
    if (listEl) {
      listEl.style.minHeight = `${listEl.offsetHeight}px`;
      lockListHeightUntil = now + SQUELCH_MS + 100;
      // Safety unlock even if no further renders happen
      setTimeout(() => {
        if (listEl && Date.now() >= lockListHeightUntil) listEl.style.minHeight = "";
      }, Math.max(0, lockListHeightUntil - now + 5));
    }
  };

  const postSquelchRenderMaybe = () => {
    const delay = Math.max(0, squelchHydrationUntil - Date.now() + 10);
    setTimeout(() => {
      if (Date.now() >= squelchHydrationUntil) {
        if (!touchedDuringSquelch) renderList(); // render only if watchers stayed quiet
        touchedDuringSquelch = false; // reset either way
      }
    }, delay);
  };

  // ===========================================================================
  // Data model
  // ===========================================================================
  const byId = new Map();
  const unreadIds = new Set();
  const readIds = new Set();
  const selected = new Set();

  const upsertMany = (items, bucket) => {
    for (const it of items || []) {
      if (!it || !it.id) continue;
      byId.set(it.id, it);
      if (bucket === "unread") {
        unreadIds.add(it.id); readIds.delete(it.id);
      } else {
        readIds.add(it.id); unreadIds.delete(it.id);
      }
    }
  };

  const moveIds = (ids, fromSet, toSet) => {
    let moved = 0;
    for (const id of ids) {
      if (fromSet.has(id)) { fromSet.delete(id); toSet.add(id); moved++; }
    }
    return moved;
  };

  // ===========================================================================
  // UI state
  // ===========================================================================
  let currentTab = "unread";
  let lastIndexForShift = null;
  const pageByTab = { unread: 0, read: 0 }; // 0-based per tab
  let pageMenuEl = null;                    // ephemeral page picker

  const renderCounts = () => {
    if (tabUnreadBtn) tabUnreadBtn.textContent =
      `Unread${unreadIds.size ? ` (${unreadIds.size})` : ""}`;
    if (tabReadBtn) tabReadBtn.textContent =
      `Read${readIds.size ? ` (${readIds.size})` : ""}`;
  };

  const updateActionButton = () => {
    if (!actionBtn) return;

    if (currentTab === "unread") {
      const selInCurrent = [...selected].filter((id) => unreadIds.has(id));
      if (selInCurrent.length) {
        actionBtn.disabled = false;
        actionBtn.textContent = `Mark Selected as Read (${selInCurrent.length})`;
      } else {
        actionBtn.disabled = unreadIds.size === 0;
        actionBtn.textContent = "Mark All as Read";
      }
      return;
    }

    const selInCurrent = [...selected].filter((id) => readIds.has(id));
    if (selInCurrent.length) {
      actionBtn.disabled = false;
      actionBtn.textContent = `Mark Selected as Unread (${selInCurrent.length})`;
    } else {
      actionBtn.disabled = readIds.size === 0;
      actionBtn.textContent = "Mark All as Unread";
    }
  };

  const totalPagesForTab = (tab) => {
    const total = (tab === "unread" ? unreadIds : readIds).size;
    return Math.max(1, Math.ceil(total / PAGE_SIZE));
  };

  const clampPageForTab = (tab) => {
    const last = totalPagesForTab(tab) - 1;
    pageByTab[tab] = Math.min(Math.max(pageByTab[tab], 0), last);
  };

  const renderPagination = (totalCount) => {
    if (!pagEl) return;
    const totalPages = Math.max(1, Math.ceil(totalCount / PAGE_SIZE));
    const idx = pageByTab[currentTab];
    if (prevBtn) prevBtn.disabled = idx <= 0;
    if (nextBtn) nextBtn.disabled = idx >= totalPages - 1;
    if (pageBtn) {
      pageBtn.textContent = `${idx + 1} / ${totalPages} ▾`;
      pageBtn.setAttribute("aria-expanded", String(!!pageMenuEl));
      pageBtn.setAttribute("aria-label", `Page ${idx + 1} of ${totalPages}`);
    }
  };

  const getItemsForTab = (tab) =>
    [...(tab === "unread" ? unreadIds : readIds)]
      .map((id) => byId.get(id))
      .filter(Boolean)
      .sort(bySentAtDesc);

  const envelopeSvg = (isUnread) => isUnread
    ? `
      <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true">
        <rect x="3" y="5" width="18" height="14" rx="2"></rect>
        <path d="M3 7l9 6 9-6"></path>
      </svg>` // closed envelope (unread)
    : `
      <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true">
        <path d="M3 9l9-6 9 6"></path>
        <path d="M21 9v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V9"></path>
        <path d="M3 9l9 6 9-6"></path>
      </svg>`; // open envelope (read)

      // Minimal "bp5-like" 16px stroke icons
    const bpIcon = {
      clock16: () => `
        <svg class="bp5ish-icon" viewBox="0 0 16 16" width="16" height="16"
            fill="none" stroke="currentColor" stroke-width="1.6"
            stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <circle cx="8" cy="8" r="6.4"></circle>
          <path d="M8 4.5v3.7l2.6 1.3"></path>
        </svg>`,
      documentOpen16: () => `
        <svg class="bp5ish-icon" viewBox="0 0 16 16" width="16" height="16"
            fill="none" stroke="currentColor" stroke-width="1.6"
            stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <!-- document with dog-ear -->
          <path d="M3.5 2.5h5l3 3v7.0a2 2 0 0 1-2 2h-6a2 2 0 0 1-2-2v-8a2 2 0 0 1 2-2z"></path>
          <path d="M8.5 2.5v2a1.5 1.5 0 0 0 1.5 1.5h2"></path>
          <!-- open (launch) arrow -->
          <path d="M6 10l4.5-4.5"></path>
          <path d="M9 4.5h1.5V6"></path>
        </svg>`
    };


      const renderList = () => {
        if (!listEl) return;

        if (Date.now() >= suppressBusyUntil) {
          listEl.setAttribute("aria-busy", "true");
        }

        const allItems = getItemsForTab(currentTab);
        clampPageForTab(currentTab);
        const start = pageByTab[currentTab] * PAGE_SIZE;
        const items = allItems.slice(start, start + PAGE_SIZE);

        listEl.innerHTML = "";
        lastIndexForShift = null;

        items.forEach((it, idx) => {
          const article = document.createElement("article");
          article.className = "nap-item";
          article.setAttribute("role", "listitem");
          article.dataset.id = it.id;

          const title = escapeHtml(it.title || "(no title)");
          const message = escapeHtml((it.message || "").trim()).replace(/\n/g, "<br>");
          const sentAtISO = it.sentAt || "";
          const sentAtText = fmtTime(sentAtISO);
          const isChecked = selected.has(it.id);
          const matterId = it.matterId || it.matter_id || null;
          const isUnread = unreadIds.has(it.id);

          const ceVal = asString(it.caseEvaluation).trim();

          // Reminder → show on same row as time
          const isReminder = asString(it.notificationType).trim().toLowerCase() === "reminder";
          const reminderSrc =  "Reminder";
          const reminderBadge = isReminder
            ? `<span class="nap-badge nap-badge-warning" title="${escapeHtml(reminderSrc)}" aria-label="${escapeHtml(reminderSrc)}">
                ${bpIcon.clock16()}${escapeHtml(reminderSrc)}
              </span>`
            : "";


          article.innerHTML = `
            <header class="nap-item-head">
              <a class="nap-link" href="#" role="button" data-matter-id="${matterId ? escapeHtml(matterId) : ''}">${title}</a>
              <button class="nap-open" type="button" aria-label="${isUnread ? "Mark as read" : "Mark as unread"}" title="${isUnread ? "Mark as read" : "Mark as unread"}">
                ${envelopeSvg(isUnread)}
              </button>
            </header>

            ${ceVal ? `
              <div class="nap-meta-row">
                <a href="#" class="nap-link nap-ce" data-ce="${escapeHtml(ceVal)}" title="Open Case Evaluation">
                  <span>Case Evaluation</span>
                  ${bpIcon.documentOpen16()}
                </a>
              </div>` : ""}


            <div class="nap-row">
              <label class="nap-checkbox nap-checkbox-lg" aria-label="Select notification">
                <input type="checkbox" class="nap-select" ${isChecked ? "checked" : ""} aria-checked="${isChecked}">
                <span class="checkmark" aria-hidden="true"></span>
              </label>

              <div class="nap-card nap-card-clickable"><p>${message}</p></div>
            </div>

            <div class="nap-foot">
              ${reminderBadge}
              <div class="nap-time"><time datetime="${escapeHtml(sentAtISO)}">${escapeHtml(sentAtText)}</time></div>
            </div>
          `;

          // Title click
          const titleEl = article.querySelector('.nap-link[data-matter-id]');
          titleEl?.addEventListener("click", (e) => {
            e.preventDefault();
            const mid = matterId || titleEl.getAttribute("data-matter-id") || "";
            if (mid) SF?.triggerEvent?.("openMatter", String(mid));
            else trigger("openNotification", it);
          });
          try { titleEl.style.cursor = "pointer"; } catch {}

          // Toggle read/unread
          const openBtn = article.querySelector(".nap-open");
          openBtn?.addEventListener("click", () => {
            const notifTypeId = getNotificationTypeId();
            const ref = { typeId: notifTypeId, primaryKey: { id: String(it.id) } };

            if (unreadIds.has(it.id)) {
              startSmoothingWindow();
              selected.delete(it.id);
              moveIds([it.id], unreadIds, readIds);
              renderCounts(); updateActionButton(); renderList();
              trigger("collectNotificationToMark", { notifications: [ref] });
              postSquelchRenderMaybe();
            } else {
              startSmoothingWindow();
              selected.delete(it.id);
              moveIds([it.id], readIds, unreadIds);
              renderCounts(); updateActionButton(); renderList();
              trigger("collectNotificationToMarkUnread", { notifications: [ref] });
              postSquelchRenderMaybe();
            }
          });
          try { openBtn.style.cursor = "pointer"; } catch {}

          // CE click
          const ceEl = article.querySelector(".nap-ce");
          ceEl?.addEventListener("click", (e) => {
            e.preventDefault();
            const ce = ceEl.getAttribute("data-ce");
            if (ce) trigger("openCaseEvaluation", String(ce));
          });

          // Selection
          const cb = article.querySelector(".nap-select");
          cb.addEventListener("click", (e) => e.stopPropagation());
          cb.addEventListener("change", (e) => {
            const checked = e.currentTarget.checked;
            const idsInView = items.map((x) => x.id);
            if (e.shiftKey && lastIndexForShift != null) {
              const s = Math.min(lastIndexForShift, idx);
              const eidx = Math.max(lastIndexForShift, idx);
              for (const id of idsInView.slice(s, eidx + 1)) {
                if (checked) selected.add(id); else selected.delete(id);
              }
            } else {
              if (checked) selected.add(it.id); else selected.delete(it.id);
              lastIndexForShift = idx;
            }
            trigger("notificationSelectionChanged", { selected: [...selected] });
            updateActionButton();
            cb.setAttribute("aria-checked", String(checked));
          });

          listEl.appendChild(article);
        });

        renderPagination(allItems.length);
        listEl.setAttribute("aria-busy", "false");

        if (Date.now() >= lockListHeightUntil) {
          listEl.style.minHeight = "";
        }

        updateActionButton();
      };





  // ===========================================================================
  // Pagination page picker
  // ===========================================================================
  const closePageMenu = () => {
    if (pageMenuEl && pageMenuEl.parentNode) pageMenuEl.parentNode.removeChild(pageMenuEl);
    pageMenuEl = null;
    if (pageBtn) pageBtn.setAttribute("aria-expanded", "false");
    document.removeEventListener("click", onDocClickClose, true);
    document.removeEventListener("keydown", onEscClose, true);
  };

  const onDocClickClose = (e) => {
    if (!pageMenuEl) return;
    if (pageMenuEl.contains(e.target) || pageBtn.contains(e.target)) return;
    closePageMenu();
  };
  const onEscClose = (e) => { if (e.key === "Escape") closePageMenu(); };

  const openPageMenu = () => {
    if (!pageBtn || !pagEl) return;
    closePageMenu();

    const total = totalPagesForTab(currentTab);
    if (total <= 1) return;

    const rect = pageBtn.getBoundingClientRect();

    pageMenuEl = document.createElement("div");
    pageMenuEl.className = "nap-page-menu";
    pageMenuEl.setAttribute("role", "listbox");
    pageMenuEl.setAttribute("aria-label", "Select page");
    Object.assign(pageMenuEl.style, {
      position: "fixed",
      zIndex: "9999",
      background: "var(--bg-color)",
      border: "1px solid var(--border-color)",
      borderRadius: "8px",
      boxShadow: "0 8px 24px rgba(0,0,0,.3)",
      padding: "6px",
      maxHeight: "40vh",
      overflow: "auto",
      minWidth: "120px",
      visibility: "hidden"
    });

    for (let i = 0; i < total; i++) {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "nap-btn nap-btn-ghost";
      Object.assign(btn.style, {
        display: "block",
        width: "100%",
        textAlign: "left",
        padding: "6px 10px",
        border: "0",
        background: "transparent",
        color: "var(--text-light)",
        cursor: "pointer"
      });
      btn.textContent = `Page ${i + 1}`;
      btn.setAttribute("role", "option");
      btn.setAttribute("aria-selected", String(i === pageByTab[currentTab]));
      btn.addEventListener("click", () => {
        pageByTab[currentTab] = i;
        closePageMenu();
        if (listEl) listEl.scrollTop = 0;
        renderList();
      });
      pageMenuEl.appendChild(btn);
    }

    document.body.appendChild(pageMenuEl);

    const pad = 8, gap = 6;
    const menuHNatural = Math.min(pageMenuEl.scrollHeight, Math.floor(window.innerHeight * 0.4));
    const rectBottom = rect.bottom;
    const spaceBelow = Math.max(0, window.innerHeight - rectBottom - pad);
    const spaceAbove = Math.max(0, rect.top - pad);

    let placement = "bottom"; let top;
    if (menuHNatural <= spaceBelow) top = rectBottom + gap;
    else if (menuHNatural <= spaceAbove) { placement = "top"; top = rect.top - menuHNatural - gap; }
    else if (spaceBelow >= spaceAbove) { pageMenuEl.style.maxHeight = `${spaceBelow}px`; top = rectBottom + gap; }
    else { placement = "top"; pageMenuEl.style.maxHeight = `${spaceAbove}px`; top = rect.top - Math.min(menuHNatural, spaceAbove) - gap; }

    const menuW = Math.max(pageMenuEl.offsetWidth, 120);
    let left = rect.left;
    if (left + menuW > window.innerWidth - pad) left = Math.max(pad, window.innerWidth - menuW - pad);
    if (left < pad) left = pad;

    pageMenuEl.style.left = `${left}px`;
    pageMenuEl.style.top = `${top}px`;
    pageMenuEl.style.visibility = "visible";
    pageMenuEl.dataset.placement = placement;

    pageBtn.setAttribute("aria-expanded", "true");

    Promise.resolve().then(() => {
      document.addEventListener("click", onDocClickClose, true);
      document.addEventListener("keydown", onEscClose, true);
    });
  };

  // ===========================================================================
  // Tab activation
  // ===========================================================================
  // Initial pick stays data-aware; but we DO NOT auto-switch tabs later.
  const chooseInitialTab = () =>
    (unreadIds.size > 0 ? "unread" : (readIds.size > 0 ? "read" : "unread"));

  const setActiveTab = (tab) => {
    currentTab = tab;
    [tabUnreadBtn, tabReadBtn].forEach((b) => b?.classList.remove("is-active"));
    (tab === "unread" ? tabUnreadBtn : tabReadBtn)?.classList.add("is-active");
    selected.clear();
    pageByTab[tab] = 0;
    renderCounts();
    if (listEl) listEl.scrollTop = 0;
    renderList();
  };

  const refreshUIAfterMutation = () => {
    // No auto-switching between tabs; just keep user on current tab.
    clampPageForTab("unread");
    clampPageForTab("read");
    selected.clear();
    renderCounts();
    updateActionButton();
    renderList();
  };

  // ===========================================================================
  // Action: Mark Read / Unread (optimistic)
  // ===========================================================================
  actionBtn?.addEventListener("click", () => {
    const notifTypeId = getNotificationTypeId();

    if (currentTab === "unread") {
      // → Mark selected/all as READ
      const selectedInUnread = [...selected].filter((id) => unreadIds.has(id));
      const ids = selectedInUnread.length ? selectedInUnread : [...unreadIds];
      if (!ids.length) return;

      const notifRefs = ids.map((id) => ({ typeId: notifTypeId, primaryKey: { id: String(id) } }));

      // UI smoothing (cover optimistic + post-squelch)
      startSmoothingWindow();

      moveIds(ids, unreadIds, readIds); // optimistic
      refreshUIAfterMutation();

      trigger("collectNotificationToMark", { notifications: notifRefs });

      postSquelchRenderMaybe();

    }

    if (currentTab === "read") {
      // → Mark selected/all as UNREAD
      const selectedInRead = [...selected].filter((id) => readIds.has(id));
      const ids = selectedInRead.length ? selectedInRead : [...readIds];
      if (!ids.length) return;

      const notifRefs = ids.map((id) => ({ typeId: notifTypeId, primaryKey: { id: String(id) } }));

      // Symmetric UI smoothing
      startSmoothingWindow();

      moveIds(ids, readIds, unreadIds); // optimistic
      refreshUIAfterMutation();

      trigger("collectNotificationToMarkUnread", { notifications: notifRefs });

      postSquelchRenderMaybe();
    }
  });

  // ===========================================================================
  // Seed + passive live updates (watchers honor squelch; NO auto tab switch)
  // ===========================================================================
  const unreadSeed = toArray(fromState("ff_fetch_unread_notifications"));
  const readSeed = toArray(fromState("ff_fetch_read_notifications"));
  upsertMany(unreadSeed, "unread");
  upsertMany(readSeed, "read");
  renderCounts();
  setActiveTab(chooseInitialTab());

  const hydrate = (nv, bucket) => {
    upsertMany(toArray(nv), bucket);
    renderCounts();
    if (Date.now() < squelchHydrationUntil) { touchedDuringSquelch = true; return; } // squelch briefly
    renderList();
  };

  // watch("ff_fetch_unread_notifications", (nv) => hydrate(nv, "unread"));
  watch("ff_fetch_read_notifications",  (nv) => hydrate(nv, "read"));

  // ===========================================================================
  // Tabs & pagination
  // ===========================================================================
  tabUnreadBtn?.addEventListener("click", () => setActiveTab("unread"));
  tabReadBtn?.addEventListener("click", () => setActiveTab("read"));

  prevBtn?.addEventListener("click", () => {
    pageByTab[currentTab]--;
    clampPageForTab(currentTab);
    if (listEl) listEl.scrollTop = 0;
    renderList();
  });

  nextBtn?.addEventListener("click", () => {
    pageByTab[currentTab]++;
    clampPageForTab(currentTab);
    if (listEl) listEl.scrollTop = 0;
    renderList();
  });

  pageBtn?.addEventListener("click", () => {
    if (pageMenuEl) closePageMenu(); else openPageMenu();
  });
})();

styles.css:
/*
