template.css:
/* FONT */
@font-face {
  font-family: "Inter";
  font-style: normal;
  font-weight: 400;
  src: url("https://hence-app-lib.s3.eu-west-2.amazonaws.com/font/Inter-Regular.ttf") format("truetype");
  font-display: swap;
}

/* THEME TOKENS */
:root{
  --bg-canvas:#020e2e;
  --bg-color:#17213e;
  --bg-l2:#13244c;
  --bg-l3:#1a2f58;
  --border-color:#32467d;
  --text-light:#e6efff;
  --text-muted:#a7bbf1;
  --text-meta:#AFBCDF;
  --primary:#3CA4FF;
}

/* BASELINES */
html, body{
  background-color: var(--bg-canvas);
  color: var(--text-light);
  font-family: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif;
  margin: 0;
}

/* ROOT */
.w_in_app_notification,
.w_in_app_notification *{ box-sizing: border-box; }

.w_in_app_notification{
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  color:var(--text-light);
  background:var(--bg-canvas);
  width:100%;
  height: 100dvh;
	min-height: 0;
  min-height:0;
  display:flex;
  flex-direction:column;
  overflow:auto;
  margin:0;
  padding:0;
  border-left:1px solid var(--border-color);
}

.hence-drawer_md .body-container-widget .w_in_app_notification{
  height:100%;
  min-height:0;
}

/* HEADER */
.w_in_app_notification .nap-top{
  position:sticky; top:0; z-index:2;
  background:var(--bg-color);
  padding:12px 16px 10px;
  border-bottom:2px solid var(--border-color);
  display:grid;
  grid-template-columns: 1fr auto;
  grid-template-rows: auto auto;
  grid-template-areas:
    "hd   hd"
    "tabs action";
  column-gap:12px;
  row-gap:6px;
}
.w_in_app_notification .nap-hd{ grid-area: hd; margin:0; display:flex; align-items:center; gap:8px; }
.w_in_app_notification .nap-tabs{ grid-area: tabs; display:flex; gap:18px; padding:6px 0 10px; align-self:end; }
.w_in_app_notification .nap-top .nap-btn{ grid-area: action; justify-self:end; align-self:end; }

.w_in_app_notification .nap-title{ margin:0; font-weight:700; font-size:16px; }
.w_in_app_notification .nap-bell{
  display:inline-flex; width:26px; height:26px; align-items:center; justify-content:center;
  border-radius:6px; background:var(--bg-l2); color:var(--primary);
}
.w_in_app_notification .nap-more{
  margin-left:auto; background:none; border:0; color:var(--text-light); opacity:.8;
  font-size:18px; line-height:1;
}

/* TABS */
.w_in_app_notification .nap-tab{
  appearance:none; background:none; border:0; color:var(--text-muted);
  font-weight:700; padding:6px 0; position:relative; cursor:pointer;
}
.w_in_app_notification .nap-tab.is-active{ color:var(--text-light); }
.w_in_app_notification .nap-tab.is-active::after{
  content:""; position:absolute; left:0; right:0; bottom:-8px; height:2px; background:var(--primary);
}

/* BUTTONS */
.w_in_app_notification .nap-btn{
  appearance:none; border:1px solid var(--border-color); border-radius:6px;
  background:var(--bg-l2); color:var(--text-light); padding:9px 12px; font-weight:700;
}
.w_in_app_notification .nap-btn:hover{ filter:brightness(1.08); }
.w_in_app_notification .nap-btn-primary{ background:var(--primary); border-color:transparent; color:#041222; }
.w_in_app_notification .nap-btn-block{ display:block; width:100%; }
.w_in_app_notification .nap-top .nap-btn-block{ display:inline-flex; width:auto; white-space:nowrap; padding:8px 12px; }
.w_in_app_notification .nap-btn,
.w_in_app_notification .nap-icon,
.w_in_app_notification .nap-open,
.w_in_app_notification .nap-link,
.w_in_app_notification .nap-more {
  cursor: pointer;
}
/* .w_in_app_notification button:disabled,
.w_in_app_notification .nap-btn[disabled],
.w_in_app_notification .nap-icon[disabled]{
  cursor: not-allowed;
  opacity: .6;
} */

/* LIST */
.w_in_app_notification .nap-list{
  flex:1 1 auto; min-height:0;
  padding:10px 16px; background:var(--bg-canvas); overscroll-behavior:contain;
  font-size:14px; line-height:1.45;
}

.w_in_app_notification .nap-item{
  background-color:#17213E;
  border-radius:6px;
  padding:10px 12px;
}
.w_in_app_notification .nap-item + .nap-item{ margin-top:10px; }
.w_in_app_notification .nap-item:hover{ box-shadow: inset 0 0 0 100vmax rgba(255,255,255,0.05); }

.w_in_app_notification .nap-item-head{ display:flex; align-items:center; gap:10px; }
.w_in_app_notification .nap-link{ color:var(--primary); text-decoration:none; font-weight:700; font-size:1em; }
.w_in_app_notification .nap-link:hover{ text-decoration:underline; }
.w_in_app_notification .nap-open{
  margin-left:auto; width:28px; height:28px; display:inline-flex; align-items:center; justify-content:center;
  border-radius:6px; border:1px solid var(--border-color); background:var(--bg-color); color:var(--text-light);
}

/* CHECKBOX (scoped) */
.w_in_app_notification .nap-checkbox{ position:relative; width:20px; height:20px; flex:0 0 20px; }
.w_in_app_notification .nap-checkbox.nap-checkbox-lg{ width:24px; height:24px; }
.w_in_app_notification .nap-checkbox input{
  position:absolute; inset:0; width:100%; height:100%; margin:0; opacity:0; cursor:pointer;
}
.w_in_app_notification .nap-checkbox .checkmark{
  position:absolute; inset:0; border:1px solid #ffffff; border-radius:3px; background:transparent;
}
.w_in_app_notification .nap-checkbox .checkmark::after{
  content:""; position:absolute; display:none; top:3px; left:7px; width:6px; height:12px;
  border:solid #fff; border-width:0 2px 2px 0; transform:rotate(45deg);
}
.w_in_app_notification .nap-checkbox input:checked + .checkmark{
  background:var(--primary); border-color:var(--primary);
}
.w_in_app_notification .nap-checkbox input:checked + .checkmark::after{ display:block; }
.w_in_app_notification .nap-checkbox input:disabled + .checkmark{
  color:rgba(255,255,255,0.1); background-color:rgba(255,255,255,0.1); border-color:rgba(255,255,255,0.2);
}
.w_in_app_notification .nap-checkbox,
.w_in_app_notification .nap-checkbox .checkmark {
  cursor: pointer;
}

/* CARD */
.w_in_app_notification .nap-card{
  margin-top:8px; background:var(--bg-l3); border:1px solid var(--border-color);
  border-radius:8px; padding:12px 14px;
}
.w_in_app_notification .nap-card p{ margin:0; }
.w_in_app_notification .nap-card p + p{ margin-top:6px; }
.w_in_app_notification .nap-card p{ font-size:0.95em; }
.w_in_app_notification .nap-muted{ color:var(--text-muted); }

/* OUTSIDE-CHECKBOX ROW ALIGNMENT */
.w_in_app_notification .nap-row{ display:flex; align-items:flex-start; gap:10px; margin-top:10px;}
.w_in_app_notification .nap-row .nap-card{ margin-top:0; }
.w_in_app_notification .nap-row .nap-checkbox{
  margin-top:18px;            /* equals .nap-card padding-top */
  padding:6px;                /* larger hit area */
}

/* TIMESTAMP */
.w_in_app_notification .nap-time{ margin-top:6px; display:flex; justify-content:flex-end; }
.w_in_app_notification .nap-time time{
  font-size:12px; color:var(--text-meta); background:transparent;
  border:0; border-radius:0; padding:0;
}

/* PAGINATION */
.w_in_app_notification .nap-pag{
  display:flex; gap:10px; align-items:center; justify-content:center;
  padding:10px 16px 14px; border-top:1px solid var(--border-color); background:var(--bg-color);
}
.w_in_app_notification .nap-icon{
  width:30px; height:30px; border-radius:6px; border:1px solid var(--border-color);
  background:var(--bg-l2); color:var(--text-light);
}
.w_in_app_notification .nap-btn-ghost{ background:transparent; color:var(--text-light); }
.w_in_app_notification .nap-page-menu button { cursor: pointer; }

/* FOCUS */
.w_in_app_notification .nap-tab:focus-visible,
.w_in_app_notification .nap-btn:focus-visible,
.w_in_app_notification .nap-icon:focus-visible,
.w_in_app_notification .nap-open:focus-visible,
.w_in_app_notification .nap-link:focus-visible,
.w_in_app_notification .nap-checkbox input:focus-visible + .checkmark{
  outline:2px solid var(--primary);
  outline-offset:2px;
}

/* RESPONSIVE */
@media (max-width: 520px){
  .w_in_app_notification .nap-top{
    grid-template-columns: 1fr;
    grid-template-rows: auto auto auto;
    grid-template-areas:
      "hd"
      "tabs"
      "action";
  }
  .w_in_app_notification .nap-top .nap-btn-block{
    width:100%;
    justify-self:stretch;
  }
  .w_in_app_notification .nap-top{ padding-left:12px; padding-right:12px; }
  .w_in_app_notification .nap-list{ padding-left:12px; padding-right:12px; }
}

/* .nap-scroll{ flex:1 1 auto; min-height:0; overflow:auto; }
.nap-top{ position:sticky; top:0; z-index:2; } */

.w_in_app_notification .nap-meta-row{
  margin-top: 4px;
}
.w_in_app_notification .nap-meta-row .nap-ce{
  font-weight: 600;
  font-size: 0.95em;
}

.w_in_app_notification .nap-meta-row{
  margin-top: 4px;
}

.w_in_app_notification .nap-meta-row .nap-ce{
  font-weight: 600;
  font-size: 0.95em;
}

.w_in_app_notification .nap-badge{
  display:inline-flex;
  align-items:center;
  padding:2px 8px;
  border-radius:999px;
