 */
___id-placeholder___ {
  width: 100%;
  height: 100%;
}

template.css:
/* Typeface */
@font-face {
  font-family: "Inter";
  font-style: normal;
  font-weight: 400;
  src: url("https://hence-app-lib.s3.eu-west-2.amazonaws.com/font/Inter-Regular.ttf") format("truetype");
}

/* Theme */
:root {
  --bg-canvas: #020e2e;
  --bg-color:  #17213e;
  --bg-l2:     #13244c;
  --bg-l3:     #1a2f58;
  --border-color: #32467d;
  --text-light:  #e6efff;
  --text-muted:  #a7bbf1;
  --text-meta:   #AFBCDF;
  --primary:     #3CA4FF;

  --wc-cell-h:    104px;
  --wc-cell-h-md: 88px;
  --wc-cell-h-sm: 72px;

  /* Event sizing */
  --wc-event-min-h: 58px;  /* month cell cards ≈ timeline */
  --wc-event-gap:   8px;   /* vertical spacing between cards */
	--wc-filter-w: 180px; 
}

html, body {
  margin: 0;
  background: var(--bg-canvas);
  color: var(--text-light);
  font-family: "Inter", sans-serif;
}

/* Widget scope */
#w_calendar html, #w_calendar body {
  background: var(--bg-canvas);
  color: var(--text-light);
  font-family: "Inter", sans-serif;
}
#w_calendar {
  --wc-cell-h:    128px;
  --wc-cell-h-md: 112px;
  --wc-cell-h-sm: 96px;
  --wc-event-min-h: 60px;
  padding: 8px 12px;
}

/* ---------- Top bar / filters ---------- */
.wc-back-row { padding: 12px 16px 0; background: var(--bg-color); }
.wc-back-btn {
  background: var(--bg-l2); color: var(--text-light);
  border: 1px solid var(--border-color); border-radius: 6px;
  padding: 6px 12px; font-size: 14px; cursor: pointer;
  transition: background-color .15s, border-color .15s;
}
.wc-back-btn:hover { border-color: var(--primary); background: var(--bg-l3); }
.wc-back-btn:focus { outline: 2px solid var(--primary); outline-offset: 2px; }

.wc-filters {
  display: flex; align-items: center; justify-content: flex-start;
  gap: 10px; padding: 8px 16px 12px; background: var(--bg-color); flex-wrap: wrap;
}
.wc-filters__left { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.wc-filters__right { margin-left: 0; display: flex; align-items: center; gap: 8px; }

.wc-select, .wc-search {
  background: var(--bg-l2); color: var(--text-light);
  border: 1px solid var(--border-color); border-radius: 6px;
  padding: 6px 12px; font-size: 14px; cursor: pointer;
}
.wc-search { width: 220px; }
.wc-select:focus, .wc-search:focus { outline: 2px solid var(--primary); outline-offset: 2px; box-shadow: none; }

.wc-reset-btn {
  background: var(--bg-l2); color: var(--text-light);
  border: 1px solid var(--border-color); border-radius: 999px;
  padding: 4px 10px; height: 34px; line-height: 1; font-size: 12px; cursor: pointer;
}
.wc-reset-btn:hover { border-color: var(--primary); }
.wc-reset-btn:active { transform: translateY(1px); }
.wc-reset-btn:focus { outline: 2px solid var(--primary); outline-offset: 2px; }

/* ---------- Calendar frame ---------- */
.wc-calendar {
  background: var(--bg-color);
  border: 1px solid var(--border-color);
  border-radius: 10px;
  overflow: hidden;
  display: flex; flex-direction: column;
}
.wc-calendar__header {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 10px 12px;
  background: var(--bg-l2);
  border-bottom: 1px solid var(--border-color);
  position: relative;
}

.wc-calendar__title {
  padding: 6px 8px;; font-weight: 700; letter-spacing: .5px; font-size: 14px; color: var(--text-light);
}
.wc-nav {
  background: var(--bg-l2); color: var(--text-light);
  border: 1px solid var(--border-color); border-radius: 10px;
  width: 32px; height: 32px; line-height: 30px; text-align: center;
  cursor: pointer; transition: border-color .15s, background-color .15s, transform .05s;
}
.wc-nav:hover { border-color: var(--primary); }
.wc-nav:active { transform: scale(.97); }
.wc-nav:focus { outline: 2px solid var(--primary); outline-offset: 2px; }

.wc-calendar__weekdays {
  display: grid; grid-template-columns: repeat(7, 1fr);
  padding: 6px 8px; background: var(--bg-l2); border-bottom: 1px solid var(--border-color);
  font-size: 11px; color: var(--text-meta);
}
.wc-calendar__weekdays > div { text-align: left; padding-left: 56px; padding-right: 0; }

.wc-calendar__grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  grid-auto-rows: var(--wc-cell-h);
}
@media (max-width: 1100px) { .wc-calendar__grid { grid-auto-rows: var(--wc-cell-h-md); } }
@media (max-width: 800px)  { .wc-calendar__grid { grid-auto-rows: var(--wc-cell-h-sm); } }

/* ---------- Day cell + reserved spaces ---------- */
.wc-day {
  position: relative;
  padding: 10px 6px 16px;
  border-right: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
  overflow: hidden; contain: paint;

  /* spacing tokens */
  --wc-top-gap: -5px;
  --wc-left-gap: 10px;
  --wc-chip-h: 28px;
  --wc-chip-gap: 2px;
}
.wc-day:nth-child(7n) { border-right: none; }

.wc-day__num {
  position: absolute; top: 8px; left: 8px;
  font-weight: 700; font-size: 12px; color: var(--text-light);
  z-index: 5;
}
.wc-day.is-muted .wc-day__num { color: var(--text-muted); }

/* disable the old spacer */
.wc-day::after { display: none; }

/* Use full cell minus day number + chip areas.
   Grid makes a single card fill the cell; multiple share space equally. */
.wc-day__list{
  margin-top: var(--wc-top-gap);
  padding: 0 6px calc(var(--wc-chip-h) + var(--wc-chip-gap)) var(--wc-left-gap);
  height: calc(100% - var(--wc-top-gap));
  max-height: calc(100% - var(--wc-top-gap));
  box-sizing: border-box;

  display: grid;
  grid-auto-rows: minmax(var(--wc-event-min-h), 1fr);
  gap: var(--wc-event-gap);
  overflow: visible;
}
.wc-day.is-overflow .wc-day__list{ overflow: hidden; }

/* ---------- Event card (month cell) ---------- */
.wc-event{
  display: flex; flex-direction: column;

  /* closer to timeline look */
/*   background: rgba(26,47,88,.96); */
  color: var(--text-light);
  border: 1px solid rgba(60,164,255,.55);
  border-radius: 12px;
  box-shadow: 0 6px 14px rgba(0,0,0,.28), inset 0 0 0 1px rgba(255,255,255,.02);

  padding: 8px 10px;
  font-size: 11px;
  line-height: 1.25;
  text-decoration: none;

  height: 100%;
  min-height: 0;
  margin: 0;
  max-width: 100%;
  overflow: hidden;

  --wc-lines: 4;
}
.wc-event__title{
  font-weight: 700;
  color: #82b6ff;
  margin-bottom: 2px;
}
.wc-event__meta{ color: var(--text-meta); }

/* TEXT BEHAVIOR IN MONTH CELLS
   - Each info row (Date, Event, Stage, Matter) stays on ONE line
   - Long values are truncated with ellipsis
   - Keep a soft fade at the bottom for pleasant cut-off when multiple rows exist
*/
.wc-event__txt{
  flex: 1; min-height: 0;
  display: block;                 /* stop multi-line clamp */
  overflow: hidden;
  -webkit-mask-image: linear-gradient(180deg, #000 82%, rgba(0,0,0,0));
  mask-image: linear-gradient(180deg, #000 82%, transparent);
}
.wc-event__txt > *{
  display: block;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;        /* one-line cut for each field */
  margin: 0;                      /* tolerate <p> or <div> children */
}

/* helper if any single-line element is used */
.wc-ellipsis{ white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* Progressive tightening when crowded */
.wc-day.is-overflow .wc-event{ --wc-lines: 3; }
.wc-day.is-overflow .wc-event.is-compact{ --wc-lines: 2; }
.wc-day.is-overflow .wc-event.is-tight{ --wc-lines: 1; }

/* Bottom chip */
.wc-chip{
  position: absolute; left: 16px; right: 14px; bottom: -2px;
  display: inline-flex; align-items: center; justify-content: center;
  background: #2e4c80; color: var(--text-light);
  border: 1px solid var(--border-color); border-radius: 999px;
  padding: 8px; font-size: 11px; cursor: pointer;
  height: var(--wc-chip-h); line-height: var(--wc-chip-h);
  transition: filter .15s, transform .05s;
}
.wc-chip:hover { filter: brightness(1.1); }
.wc-chip:active { transform: translateY(1px); }
.wc-chip:focus  { outline: 2px solid var(--primary); outline-offset: 2px; }

/* Today highlight */
.wc-day.is-today .wc-day__num{
  background: var(--primary); color: #0b183a; border-radius: 6px; padding: 2px 6px;
}
.wc-day.is-spotlight{ box-shadow: inset 0 0 0 2px var(--primary); animation: wcPulse 900ms ease 1; }
@keyframes wcPulse{
  0%{ box-shadow: inset 0 0 0 0 var(--primary); }
  40%{ box-shadow: inset 0 0 0 3px var(--primary); }
  100%{ box-shadow: inset 0 0 0 2px var(--primary); }
}

.wc-today-btn{
  background: var(--bg-l2); color: var(--text-light);
  border: 1px solid var(--border-color); border-radius: 999px;
  padding: 4px 10px; height: 34px; line-height: 1; white-space: nowrap; font-size: 12px; cursor: pointer;
}
.wc-today-btn:hover { border-color: var(--primary); }
.wc-today-btn:active{ transform: translateY(1px); }
.wc-today-btn:focus { outline: 2px solid var(--primary); outline-offset: 2px; }

/* ---------- Timeline (unchanged visuals) ---------- */
.wc-timeline{
  background: var(--bg-l2);
  border-bottom: 1px solid var(--border-color);
  padding: 8px 12px; margin-bottom: 12px; position: relative;
}
.wc-timeline__title{ font-size: 12px; color: var(--text-meta); margin-bottom: 6px; position: relative; z-index: 1; }
.wc-timeline__axis{ position: relative; height: 100px; padding: 0 16px; overflow: visible; z-index: 2; }
.wc-timeline__line{
  position: absolute; left: 0; right: 0; top: 28px; height: 1px; border-radius: 999px;
  background: linear-gradient(90deg, rgba(255,255,255,0) 0%, rgba(60,164,255,.35) 18%, rgba(60,164,255,.35) 82%, rgba(255,255,255,0) 100%);
}
.wc-timeline__now{ position: absolute; top: 22px; width: 2px; height: 20px; background: var(--primary); z-index: 5; }
.wc-timeline__now::after{
  content: "Today"; position: absolute; top: -10px; left: 50%; transform: translateX(-50%);
  font-size: 10px; color: var(--text-meta); pointer-events: none; z-index: 6;
}
.wc-timeline__dot{
  position: absolute; top: 28px; width: 9px; height: 9px; background: var(--primary);
  border-radius: 50%; border: 2px solid #0d203f; transform: translateX(-50%); z-index: 4;
}
.wc-timeline__stem{ position: absolute; width: 1px; background: var(--primary); z-index: 2; }
.wc-timeline__label{
  position: absolute; left: 0; top: 0; transform: translateX(-50%);
  background: rgba(26,47,88,.95); border: 1px solid var(--primary); border-radius: 8px;
  padding: 5px 8px; font-size: 10.5px; color: var(--text-light);
  max-width: 220px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; pointer-events: none; z-index: 3;
}
a.wc-timeline__label,
a.wc-timeline__label:visited,
a.wc-timeline__label:hover,
a.wc-timeline__label:focus {
  text-decoration: none !important;
}
.wc-empty{ color: var(--text-muted); font-size: 12px; }

.wc-modal__body .wc-event__txt,
.wc-timeline .wc-event__txt{
  display: block;
  overflow: visible;
  white-space: normal;
  -webkit-line-clamp: initial;
  -webkit-mask-image: none;
  mask-image: none;
}

.wc-modal__body .wc-event__txt > *,
.wc-timeline .wc-event__txt > *{
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
}

.wc-modal__body .wc-event{
  height: auto;
  min-height: 0;
  overflow: visible;
}


/* Month picker */
.wc-monthpick{
  background: var(--bg-l2); color: var(--text-light);
  border: 1px solid var(--border-color); border-radius: 999px;
  padding: 4px 10px; height: 26px; line-height: 1; margin-left: 8px; font-size: 12px;
}
.wc-monthpick:hover{ border-color: var(--primary); }
.wc-monthpick:focus{ outline: 2px solid var(--primary); outline-offset: 2px; }

/* Misc */
.wc-tabs{ display: none !important; }

/* ---------- Searchable combobox ---------- */
.wc-combobox{ position: relative; display: inline-block; width: var(--wc-filter-w, 180px); min-width: 0; }
.wc-combobox .wc-combobox__box{
  display: grid; grid-template-columns: 1fr 24px; align-items: center;
  background: var(--bg-l2); color: var(--text-light);
  border: 1px solid var(--border-color); border-radius: 6px;
}
.wc-combobox__input{
  background: transparent; color: var(--text-light);
  border: 0; outline: none; padding: 4px 8px; font-size: 12px;
}
.wc-combobox__input::placeholder{ color: var(--text-meta); }
.wc-combobox__btn{
  background: transparent; color: var(--text-light);
  border: 0; border-left: 1px solid var(--border-color);
  height: 100%; cursor: pointer; font-size: 10px;
}
.wc-combobox.is-open .wc-combobox__box{ border-color: var(--primary); }
.wc-combobox__list{
  position: absolute; z-index: 9999; left: 0; right: 0; top: calc(100% + 4px);
  max-height: 260px; overflow: auto; padding: 4px; margin: 0; list-style: none;
  background: var(--bg-l3); color: var(--text-light);
  border: 1px solid var(--border-color); border-radius: 8px; box-shadow: 0 10px 28px rgba(0,0,0,0.35);
}
.wc-combobox__option{ padding: 6px 8px; border-radius: 6px; cursor: pointer; font-size: 13px; }
.wc-combobox__option:hover, .wc-combobox__option.is-active{ background: #2e4c80; }
.wc-combobox__option[aria-selected="true"]::after{ content: " ✓"; color: var(--primary); font-weight: 700; }
.wc-combobox__option.is-empty{ color: var(--text-meta); cursor: default; }

/* ---------- Responsive ---------- */
@media (max-width: 1100px){
  #w_calendar .wc-calendar__weekdays > div { padding-left: 44px; }
  #w_calendar .wc-day__num { top: 6px; left: 6px; }
}
@media (max-width: 900px){
  #w_calendar .wc-calendar__header{ grid-template-columns: 32px 1fr 32px; padding: 8px 10px; }
  #w_calendar .wc-calendar__title{ font-size: 13px; }
  #w_calendar .wc-monthpick{ height: 24px; font-size: 11px; }
  #w_calendar .wc-search{ width: 180px; }
  #w_calendar .wc-combobox{ min-width: 160px; }
  #w_calendar .wc-event{ font-size: 10.75px; }
  #w_calendar .wc-event__title{ font-size: 10.75px; }
}
@media (max-width: 700px){
