template.js:
/**
 * Calendar widget: month grid, filters (matter-name/matter-number/stage/event/search/df), custom month/year picker,
 * modal day agenda, upcoming timeline. Works in single-matter and all-matters modes with robust
 * label resolution and searchable comboboxes. Includes reset button and adaptive card fitting.
 */
(() => {
  'use strict';

  // DOM
  const $ = (sel) => document.querySelector(sel);
  const el = (tag, className, html) => { const n = document.createElement(tag); if (className) n.className = className; if (html != null) n.innerHTML = html; return n; };

  // State
  let matterId = null;
  let stages = [];
  let rowsUnified = [];
  let activeRows = [];
  let stageRowsResolved = [];
  const stageLookup = new Map();
  let stageDefNamesDict = {};
  let isInternal = false;

  // Filters
  let filterMatterId = '';  
  let filterMatterNameLabel = '';
  let filterStageId = '';
  let filterEventId = '';
  let searchTerm = '';
  let filterStageLabel = '';
  let filterEventLabel = '';
  let filterDfId = '';
  let filterDfLabel = '';

  // View
  const today = new Date();
  const TODAY_Y = today.getFullYear();
  const TODAY_M = today.getMonth();
  const TODAY_D = today.getDate();
  let viewMonth = TODAY_M;
  let viewYear = TODAY_Y;

  // Picker
  let pickerEl = null;
  let pickerStartYear = null;
  let pickerSelectedYear = null;

  // Modal
  let modalEl = null;
  let modalCloseFn = null;

  // Utils
  const toArray = (v) => (Array.isArray(v) ? v : v == null ? [] : (typeof v === 'string' ? (()=>{ try { const p=JSON.parse(v); return Array.isArray(p)?p:[]; } catch { return []; } })() : []));
  const mondayIndex = (dow) => (dow + 6) % 7;
  const firstWeekdayIndexMondayFirstUTC = (y, m) => mondayIndex(new Date(Date.UTC(y, m, 1)).getUTCDay());
  const daysInMonthUTC = (y, m) => new Date(Date.UTC(y, m + 1, 0)).getUTCDate();
  const daysInPrevMonthUTC = (y, m) => new Date(Date.UTC(y, m, 0)).getUTCDate();
  const parseYMD = (ymd) => { const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(ymd || '')); return m ? { year: +m[1], month: +m[2] - 1, day: +m[3] } : null; };
  const toUTCTs = (ymd) => { const p = parseYMD(ymd); return p ? Date.UTC(p.year, p.month, p.day) : NaN; };
  const fmtMMDDYYYY = (ymd) => { const p = parseYMD(ymd); if (!p) return ''; const mm = String(p.month + 1).padStart(2,'0'); const dd = String(p.day).padStart(2,'0'); return `${mm}/${dd}/${p.year}`; };
  const pad2 = (n) => String(n).padStart(2, '0');
  const setMonthInput = (y, m) => { const inp = $('.wc-monthpick'); if (inp) inp.value = `${y}-${pad2(m + 1)}`; };

  // Label caches
  const stageNameCache = new Map();
  const eventNameCache = new Map();
  const stageDefNameCache = new Map();

  const matterNameCache = new Map();
  const getMatterIdForRow = (row) => row?.matter_id ?? row?.event?.matter_id ?? null;
  const getMatterNameById = (id) => (id && matterNameCache.get(id)) || '';
  const getMatterNameForRow = (row) => {
    const mid = getMatterIdForRow(row);
    const nm = row?.matter_name
      ?? row?.event?.matter_name
      ?? row?.matter?.name
      ?? getMatterNameById(mid)
      ?? '';
    if (mid && nm && !matterNameCache.has(mid)) matterNameCache.set(mid, nm);
    return nm || '';
  };

  const extractStageDefId = (def) => { const m = String(def || '').match(/^(S[A-Za-z0-9_-]+)E/); return m ? m[1] : null; };

  function rebuildNameCaches() {
    stageNameCache.clear();
    eventNameCache.clear();
    // don't clear matterNameCache; keep learned labels across refresh; but try to enrich it
    for (const r of rowsUnified || []) {
      const evName = r?.event_name ?? r?.event?.event_name ?? r?.event?.name ?? null;
      const evIdA  = r?.event_live_id ?? null;
      const evIdB  = r?.event?.id ?? null;
      if (evName) { if (evIdA && !eventNameCache.has(evIdA)) eventNameCache.set(evIdA, evName); if (evIdB && !eventNameCache.has(evIdB)) eventNameCache.set(evIdB, evName); }

      const stName = r?.stage_name ?? r?.event?.stage_name ?? null;
      const stIdA  = r?.stage_live_id ?? r?.event_stage_live_id ?? r?.event?.stage_live_id ?? null;
      if (stName && stIdA && !stageNameCache.has(stIdA)) stageNameCache.set(stIdA, stName);

      // NEW: seed matter name cache when available
      const mid = getMatterIdForRow(r);
      const mname = r?.matter_name ?? r?.event?.matter_name ?? r?.matter?.name ?? null;
      if (mid && mname && !matterNameCache.has(mid)) matterNameCache.set(mid, mname);

      const sdef = extractStageDefId(r?.event_stage_definition_id) || extractStageDefId(r?.date_event_definition_id);
      if (sdef && stName && !stageDefNameCache.has(sdef)) stageDefNameCache.set(sdef, stName);
    }
  }

  function rebuildStageLookup() {
    stageLookup.clear();
    for (const s of toArray(stages)) {
      if (!s?.id) continue;
      stageLookup.set(s.id, {
        name: s?.name ?? null,
        rankOrder: (s?.rankOrder == null ? 0 : +s.rankOrder) || 0,
        stageDefinitionId: s?.stageDefinitionId ?? null,
        matter_id: s?.matter_id ?? null,
      });
      if (s?.stageDefinitionId && s?.name && !stageDefNameCache.has(s.stageDefinitionId)) stageDefNameCache.set(s.stageDefinitionId, s.name);
    }
    for (const s of toArray(stageRowsResolved)) {
      if (!s?.id) continue;
      const cur = stageLookup.get(s.id) || {};
      const merged = {
        name: cur.name ?? s.name ?? null,
        rankOrder: cur.rankOrder != null ? cur.rankOrder : ((s?.rankOrder == null ? 0 : +s.rankOrder) || 0),
        stageDefinitionId: cur.stageDefinitionId ?? s.stageDefinitionId ?? null,
        matter_id: cur.matter_id ?? s.matter_id ?? null,
      };
      stageLookup.set(s.id, merged);
      if (merged.stageDefinitionId && merged.name && !stageDefNameCache.has(merged.stageDefinitionId)) stageDefNameCache.set(merged.stageDefinitionId, merged.name);
    }
  }

  function ensureStageDefLabel(sdef) {
    if (!sdef) return null;
    if (stageDefNameCache.has(sdef)) return stageDefNameCache.get(sdef);
    const nm = stageDefNamesDict && stageDefNamesDict[sdef];
    if (nm) { stageDefNameCache.set(sdef, nm); return nm; }
    return null;
  }

  const getEventNameById = (id) => (id && eventNameCache.get(id)) || '';
  function getEventLabelForRow(row) {
    const name = row?.event_name ?? getEventNameById(row?.event_live_id) ?? row?.event?.event_name ?? row?.event?.name ?? '';
    if (name) {
      const evIdA = row?.event_live_id ?? null, evIdB = row?.event?.id ?? null;
      if (evIdA && !eventNameCache.has(evIdA)) eventNameCache.set(evIdA, name);
      if (evIdB && !eventNameCache.has(evIdB)) eventNameCache.set(evIdB, name);
    }
    return name;
  }
  function stageLabelForRow(row) {
    const stId = row?.stage_live_id ?? row?.event_stage_live_id ?? row?.event?.stage_live_id ?? null;
    if (!stId) return '';
    const lk = stageLookup.get(stId)?.name; if (lk) return lk;
    const direct = row?.stage_name ?? row?.event?.stage_name ?? null;
    if (direct) { stageNameCache.set(stId, direct); return direct; }
    const sdef = extractStageDefId(row?.event_stage_definition_id) || extractStageDefId(row?.date_event_definition_id);
    if (sdef && stageDefNameCache.has(sdef)) return stageDefNameCache.get(sdef);
    return 'Stage';
  }

  function getDfListForRow(row) {
    const list = Array.isArray(row?.defending_firms) ? row.defending_firms : [];
    if (list.length) return list.map(f => ({ id: f?.id || null, name: f?.name || null }));
    const id = row?.defending_firm_id || row?.event?.defending_firm_id || null;
    const name = row?.defending_firm_name || row?.event?.defending_firm_name || null;
    return id ? [{ id, name: name || null }] : [];
  }

  function dfNamesForRow(row) {
    const names = getDfListForRow(row).map(x => (x.name || '').trim()).filter(Boolean);
    const seen = new Set(); const out = [];
    for (const n of names) { const k = n.toLowerCase(); if (!seen.has(k)) { seen.add(k); out.push(n); } }
    return out;
  }

  // Normalize rows
  function normalizeRows(arr) {
    const out = [];
    for (const r of toArray(arr)) {
      const date = String(r?.date || '').slice(0, 10);
      if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) continue;
      const ev = r?.event || null;
      out.push({
        ...r,
        date,
        id: r?.id ?? null,
        matter_id: r?.matter_id ?? ev?.matter_id ?? null,
        matter_name: r?.matter_name ?? ev?.matter_name ?? r?.matter?.name ?? r?.matterName ?? null,
        stage_live_id: r?.stage_live_id ?? ev?.stage_live_id ?? null,
        event_live_id: r?.event_live_id ?? ev?.id ?? null,
        stage_name: r?.stage_name ?? ev?.stage_name ?? null,
        event: ev,
        event_name: r?.event_name ?? ev?.event_name ?? ev?.name ?? null,
        event_stage_definition_id: r?.event_stage_definition_id ?? ev?.event_stage_definition_id ?? null,
        event_stage_live_id: r?.event_stage_live_id ?? ev?.event_stage_live_id ?? null,
        rank: (r?.rank == null ? 0 : +r.rank) || 0,
        date_name: r?.date_name || 'Date',
        date_event_definition_id: r?.date_event_definition_id ?? null,
      });
    }
    return out;
  }

  // Slate I/O
  function readSlateState() {
    try {
      const st = SlateFunctions.getState?.() || {};
      console.log("Slate States: ", st);
      matterId          = st.matterId || null;
      stages            = toArray(st.f_matter_stages);
      rowsUnified       = normalizeRows(st.f_oss_matter_stage_events_dates_unified);
      stageRowsResolved = toArray(st.f_oss_stage_names_resolved);
      isInternal        = !!st.f_is_internal_user;

      stageDefNameCache.clear();
      const dict = st.f_stage_def_names || {};
      if (dict && typeof dict === 'object') for (const k in dict) { const v = dict[k]; if (v) stageDefNameCache.set(k, v); }

      rebuildStageLookup();
      rebuildNameCaches();
      chooseActiveRows();
    } catch {
      matterId = null; stages = []; rowsUnified = []; stageRowsResolved = []; activeRows = [];
      stageLookup.clear(); stageNameCache.clear(); eventNameCache.clear(); stageDefNameCache.clear();
    }
  }

  function chooseActiveRows() {
    const base = rowsUnified || [];
    if (matterId == null) {
      activeRows = filterMatterId ? base.filter(r => r.matter_id === filterMatterId || r?.event?.matter_id === filterMatterId) : base;
    } else {
      activeRows = base.filter(r => r.matter_id === matterId || r?.event?.matter_id === matterId);
    }
  }

  function watchSlateState() {
    SlateFunctions.watch?.('matterId', (v) => {
      matterId = v || null;
      filterStageId = filterEventId = filterStageLabel = filterEventLabel = '';
      filterMatterId = '';
      filterMatterNameLabel = '';
      if (matterId != null) filterMatterId = '';
      chooseActiveRows(); populateFilters(); applySearchableMode(); rebuildMonthEvents(); updateFilterVisibility(); renderAll();
    });
    SlateFunctions.watch?.('f_matter_stages', (next) => {
      stages = toArray(next);
      rebuildStageLookup(); populateFilters(); applySearchableMode(); rebuildMonthEvents(); updateFilterVisibility(); renderAll();
    });
    SlateFunctions.watch?.('f_oss_matter_stage_events_dates_unified', (next) => {
      rowsUnified = normalizeRows(next);
      rebuildNameCaches(); chooseActiveRows(); populateFilters(); applySearchableMode(); rebuildMonthEvents(); updateFilterVisibility(); renderAll();
    });
    SlateFunctions.watch?.('f_oss_stage_names_resolved', (next) => {
      stageRowsResolved = toArray(next);
      rebuildStageLookup(); populateFilters(); applySearchableMode(); rebuildMonthEvents(); updateFilterVisibility(); renderAll();
    });
    SlateFunctions.watch?.('f_stage_def_names', (next) => {
      stageDefNamesDict = next || {};
      stageDefNameCache.clear();
      for (const k in stageDefNamesDict) if (stageDefNamesDict[k]) stageDefNameCache.set(k, stageDefNamesDict[k]);
      rebuildStageLookup(); populateFilters(); applySearchableMode(); rebuildMonthEvents(); updateFilterVisibility(); renderAll();
    });
    SlateFunctions.watch?.('f_is_internal_user', (v) => {
      isInternal = !!v;
      populateFilters();
      applySearchableMode();
      updateFilterVisibility();
      rebuildMonthEvents();
      renderAll();
    });
  }

  // Back
  function wireBackButton() {
    $('#wcBackBtn')?.addEventListener('click', () => { if (matterId == null) return; SlateFunctions.triggerEvent?.('backToMatter', String(matterId)); });
  }

  // Filters UI
  let matterNameSel, matterSel, stageSel, eventSel, searchInput, dfSel;

  function ensureMatterNameSelect() {
    const left = $('.wc-filters__left'); if (!left) return null;
    matterNameSel = left.querySelector('.wc-select--matter-name');
    if (!matterNameSel) {
      matterNameSel = document.createElement('select');
      matterNameSel.className = 'wc-select wc-select--matter-name';
      matterNameSel.setAttribute('aria-label', 'Matter Name');
      left.insertBefore(matterNameSel, left.firstChild);
    }
    matterNameSel.style.display = 'none';
    return matterNameSel;
  }

  function ensureMatterSelect() {
    const left = $('.wc-filters__left'); if (!left) return null;
    matterSel = left.querySelector('.wc-select--matter');
    if (!matterSel) {
      matterSel = document.createElement('select');
      matterSel.className = 'wc-select wc-select--matter';
      matterSel.setAttribute('aria-label', 'Matter Number');
      // insert after matter-name if exists
      const before = left.querySelector('.wc-select--stage');
      left.insertBefore(matterSel, before || left.firstChild);
    }
    matterSel.style.display = 'none';
    return matterSel;
  }

  function ensureDfSelect() {
    const left = $('.wc-filters__left'); if (!left) return null;
    let df = left.querySelector('.wc-select--df');
    if (!df) {
      df = document.createElement('select');
      df.className = 'wc-select wc-select--df';
      df.setAttribute('aria-label', 'Defending Firm');
      const after = left.querySelector('.wc-select--event');
      if (after && after.parentNode) after.parentNode.insertBefore(df, after.nextSibling);
      else left.appendChild(df);
    }
    return df;
  }

  function getFilterControls() {
    const left = $('.wc-filters__left');
    ensureMatterNameSelect();
    ensureMatterSelect();
    ensureDfSelect();
    return {
      matterNameSel: left?.querySelector('.wc-select--matter-name') || null,
      matterSel:     left?.querySelector('.wc-select--matter') || null,
      stageSel:      left?.querySelector('.wc-select--stage')  || null,
      eventSel:      left?.querySelector('.wc-select--event')  || null,
      dfSel:         left?.querySelector('.wc-select--df')     || null,
      searchInput:   document.querySelector('.wc-search') || null,
    };
  }

  function getStageName(stageId) {
    if (!stageId) return '';
    const lk = stageLookup.get(stageId); if (lk?.name) return lk.name;
    if (matterId != null) { const nm = stages.find(s => s?.id === stageId)?.name; if (nm) return nm; }
    if (stageNameCache.has(stageId)) return stageNameCache.get(stageId);
    const row = activeRows.find(r => (r.stage_live_id === stageId || r.event_stage_live_id === stageId || r?.event?.stage_live_id === stageId) && (r.stage_name || r?.event?.stage_name));
    const label = row?.stage_name || row?.event?.stage_name || 'Stage';
    if (label) stageNameCache.set(stageId, label);
    return label;
  }

  // Searchable selects
  let combos = { matterName: null, matter: null, stage: null, event: null, df: null };
  function makeSearchableSelect(selectEl, { placeholder = '' } = {}) {
    if (!selectEl) return null;

    // Derive a semantic label for accessibility
    let labelText = (selectEl.getAttribute('aria-label') || '').trim();
    if (!labelText) {
      labelText =
        selectEl.classList.contains('wc-select--matter-name') ? 'Matter Name' :
        selectEl.classList.contains('wc-select--matter') ? 'Matter Number' :
        selectEl.classList.contains('wc-select--stage') ? 'Stage' :
        selectEl.classList.contains('wc-select--event') ? 'Event' :
        selectEl.classList.contains('wc-select--df') ? 'Defending Firm' : 'Filter';
    }

    const container = el('div', 'wc-combobox__wrap');
    const labelEl = el('label', 'wc-combobox__label', labelText);
    // Keep label in DOM for semantics but never display it (placeholder acts as visual cue)
    Object.assign(labelEl.style, { display: 'none' });

    const wrap = el('div', 'wc-combobox');
    wrap.innerHTML = `
      <div class="wc-combobox__box">
        <input class="wc-combobox__input" type="text" autocomplete="off"
               role="combobox" aria-autocomplete="list" aria-expanded="false"
               aria-controls="" aria-haspopup="listbox" placeholder="${placeholder}">
        <button class="wc-combobox__btn" aria-label="Open menu" tabindex="-1">▾</button>
      </div>
      <ul class="wc-combobox__list" role="listbox" hidden></ul>
    `;
    const input = wrap.querySelector('.wc-combobox__input');
    const btn   = wrap.querySelector('.wc-combobox__btn');
    const list  = wrap.querySelector('.wc-combobox__list');
    // Accessible name for SRs since visible label is hidden
    input.setAttribute('aria-label', labelText);

    list.id = `wc_list_${Math.random().toString(36).slice(2)}`;
    input.setAttribute('aria-controls', list.id);

    const inputId = `wc_cb_${Math.random().toString(36).slice(2)}`;
    input.id = inputId;
    labelEl.setAttribute('for', inputId);

    selectEl.insertAdjacentElement('afterend', container);
    container.appendChild(labelEl);
    container.appendChild(wrap);

    let items = [];
    let open = false;
    let activeIndex = -1;
    const MAX_RESULTS = 300;
    const debounce = (fn, ms = 80) => { let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); }; };

    function readOptions() {
      items = Array.from(selectEl.options).map((o) => ({
        value: o.value,
        label: o.textContent || '',
        disabled: o.disabled,
        selected: o.selected
      }));
    }
    const labelForValue = (val) => (items.find(i => i.value === val)?.label || '');

    function syncInputFromSelect() {
      const selectedVal = selectEl.value;
      const isEmpty = (selectedVal === '');
      input.value = isEmpty ? '' : (labelForValue(selectedVal) || '');
      // Always keep the intended placeholder text
      input.placeholder = (placeholder && String(placeholder)) || 'Select…';
    }

    function renderList(query = '') {
      const q = (query || '').toLowerCase();
      const pool = q ? items.filter(i => !i.disabled && i.label.toLowerCase().includes(q))
                     : items.filter(i => !i.disabled);
      const results = pool.slice(0, MAX_RESULTS);
      list.innerHTML = '';
      if (results.length === 0) {
        const li = el('li', 'wc-combobox__option is-empty', 'No matches');
        li.setAttribute('role', 'option');
        li.setAttribute('aria-disabled', 'true');
        list.appendChild(li);
        activeIndex = -1;
        return;
      }
      results.forEach((it, idx) => {
        const li = el('li', 'wc-combobox__option', it.label);
        li.setAttribute('role', 'option');
        li.setAttribute('data-value', it.value);
        li.setAttribute('aria-selected', it.value === selectEl.value ? 'true' : 'false');
        li.addEventListener('mousedown', (e) => { e.preventDefault(); commitValue(it.value); });
        list.appendChild(li);
        if (it.value === selectEl.value) activeIndex = idx;
      });
    }

    function openList() {
      if (open) return;
      open = true;
      wrap.classList.add('is-open');
      list.hidden = false;
      input.setAttribute('aria-expanded', 'true');
      renderList(input.value);
    }
    function closeList() {
      if (!open) return;
      open = false;
      wrap.classList.remove('is-open');
      list.hidden = true;
      input.setAttribute('aria-expanded', 'false');
      activeIndex = -1;
    }
    function moveActive(delta) {
      const options = Array.from(list.querySelectorAll('.wc-combobox__option:not(.is-empty)'));
      if (!options.length) return;
      const next = Math.max(0, Math.min((activeIndex < 0 ? -1 : activeIndex) + delta, options.length - 1));
      if (activeIndex >= 0) options[activeIndex].classList.remove('is-active');
      activeIndex = next;
      options[activeIndex].classList.add('is-active');
      options[activeIndex].scrollIntoView({ block: 'nearest' });
    }
    function commitValue(val) {
      if (selectEl.value === val) {
        syncInputFromSelect();
        closeList();
        return;
      }
      selectEl.value = val;
      syncInputFromSelect();
      selectEl.dispatchEvent(new Event('change', { bubbles: true }));
      closeList();
    }

    const onType = debounce(() => { if (!open) openList(); renderList(input.value); }, 80);
    input.addEventListener('focus', () => openList());
    input.addEventListener('input', onType);
    input.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowDown') { e.preventDefault(); if (!open) openList(); moveActive(1); }
      else if (e.key === 'ArrowUp') { e.preventDefault(); if (!open) openList(); moveActive(-1); }
      else if (e.key === 'Enter') {
        if (open) {
          e.preventDefault();
          const active = list.querySelector('.wc-combobox__option.is-active') ||
                         list.querySelector('.wc-combobox__option[aria-selected="true"]');
          const val = active?.getAttribute('data-value');
          if (val != null) commitValue(val);
        }
      } else if (e.key === 'Escape') { closeList(); input.select(); }
    });
    btn.addEventListener('click', (e) => { e.preventDefault(); if (open) closeList(); else { input.focus(); openList(); } });
    document.addEventListener('mousedown', (e) => { if (!container.contains(e.target)) closeList(); });

    function refreshFromSelect() { readOptions(); syncInputFromSelect(); if (open) renderList(input.value); }
    function setSearchable(on) {
      if (on) {
        container.style.display = '';
        labelEl.style.display = 'none'; // always hidden (placeholders only)
        // hide the raw select always (we show the combobox)
        selectEl.style.display = 'none';
        refreshFromSelect();
      } else {
        container.style.display = 'none';
        labelEl.style.display = 'none';
        selectEl.style.display = '';
      }
    }

    refreshFromSelect();
    return { setSearchable, refresh: refreshFromSelect, root: container, input, list, select: selectEl, label: labelEl };
  }


  function ensureComboboxes() {
    const { matterNameSel, matterSel, stageSel, eventSel, dfSel } = getFilterControls();
    if (matterNameSel && !combos.matterName) {
      combos.matterName = makeSearchableSelect(matterNameSel, { placeholder: 'Matter Name…' });
    }
    if (matterSel && !combos.matter) {
      combos.matter = makeSearchableSelect(matterSel, { placeholder: 'Matter Number…' });
    }
    if (stageSel && !combos.stage) {
      combos.stage = makeSearchableSelect(stageSel, { placeholder: 'Stage…' });
    }
    if (eventSel && !combos.event) {
      combos.event = makeSearchableSelect(eventSel, { placeholder: 'Event…' });
    }
    if (dfSel && !combos.df) {
      combos.df = makeSearchableSelect(dfSel, { placeholder: 'Defending Firm…' });
    }
  }  
  function applySearchableMode() {
    const searchable = (matterId == null);
    ensureComboboxes();
    combos.matterName?.setSearchable(searchable);
    combos.matter?.setSearchable(searchable);
    combos.stage?.setSearchable(searchable);
    combos.event?.setSearchable(searchable);
    combos.df?.setSearchable(searchable);
  }
  function refreshComboboxOptions() {
    combos.matterName?.refresh();
    combos.matter?.refresh();
    combos.stage?.refresh();
    combos.event?.refresh();
    combos.df?.refresh();
  }

  function updateFilterVisibility() {
    const { matterNameSel, matterSel, stageSel, eventSel, dfSel } = getFilterControls();
    const isAllMatters = (matterId == null);
    const matterNameCb = combos.matterName?.root, matterCb = combos.matter?.root,
          stageCb = combos.stage?.root, eventCb = combos.event?.root, dfCb = combos.df?.root;

    // Show/hide native selects (always hidden when combobox present)
    if (isAllMatters) {
      if (matterNameSel) matterNameSel.style.display = 'none';
      if (matterSel)     matterSel.style.display     = 'none';
      if (stageSel)      stageSel.style.display      = 'none';
      if (eventSel)      eventSel.style.display      = 'none';

      if (matterNameCb) matterNameCb.style.display = '';
      if (matterCb)     matterCb.style.display     = '';
      if (stageCb)      stageCb.style.display      = '';
      if (eventCb)      eventCb.style.display      = '';
    } else {
      if (matterNameSel) matterNameSel.style.display = 'none';
      if (matterSel)     matterSel.style.display     = 'none';
      if (stageSel)      stageSel.style.display      = '';
      if (eventSel)      eventSel.style.display      = '';

      if (matterNameCb) matterNameCb.style.display = 'none';
      if (matterCb)     matterCb.style.display     = 'none';
      if (stageCb)      stageCb.style.display      = 'none';
      if (eventCb)      eventCb.style.display      = 'none';
    }

    // Always hide visible labels (we rely on placeholders + aria-label)
    if (combos.matterName?.label) combos.matterName.label.style.display = 'none';
    if (combos.matter?.label)     combos.matter.label.style.display     = 'none';
    if (combos.stage?.label)      combos.stage.label.style.display      = 'none';
    if (combos.event?.label)      combos.event.label.style.display      = 'none';

    // Defending Firm visibility (internal-only)
    const showDf = !!isInternal && isAllMatters;
    if (dfSel) dfSel.style.display = 'none';
    if (dfCb)  dfCb.style.display  = showDf ? '' : 'none';
    if (combos.df?.label) combos.df.label.style.display = 'none';
  }  

  // Populate filters
  function populateFilters() {
    const ctrls = getFilterControls();
    matterNameSel = ctrls.matterNameSel;
    matterSel     = ctrls.matterSel;
    stageSel      = ctrls.stageSel;
    eventSel      = ctrls.eventSel;
    searchInput   = ctrls.searchInput;
    dfSel         = ctrls.dfSel;

    // Matter Name (label)
    if (matterNameSel) {
      const namesSet = new Map();
      for (const r of (rowsUnified || [])) {
        const nm = (getMatterNameForRow(r) || '').trim();
        if (nm) namesSet.set(nm, true);
      }
      const prev = filterMatterNameLabel;
      const options = [{ value: '', label: 'All Matter Names' }, ...[...namesSet.keys()].sort((a,b)=>a.localeCompare(b)).map(nm => ({ value: nm, label: nm }))];
      matterNameSel.innerHTML = options.map(o => `<option value="${o.value}"${o.value === prev ? ' selected' : ''}>${o.label}</option>`).join('');
      if (!options.find(o => o.value === prev)) filterMatterNameLabel = '';
      matterNameSel.style.display = 'none';
    }

    // Matter Number (id)
    if (matterSel) {
      const matterIds = Array.from(new Set((rowsUnified || []).map(r => r.matter_id).filter(Boolean))).sort();
      const prev = filterMatterId;
      const options = [{ value: '', label: 'All Matter Numbers' }, ...matterIds.map(id => ({ value: id, label: id }))];
      matterSel.innerHTML = options.map(o => `<option value="${o.value}"${o.value === prev ? ' selected' : ''}>${o.label}</option>`).join('');
      if (!options.find(o => o.value === prev)) filterMatterId = '';
      matterSel.style.display = 'none';
    }

    const rowsInScope = activeRows;

    // Stage
    if (stageSel) {
      if (matterId == null) {
        const stageByLabel = new Map();
        for (const r of rowsInScope) { const lbl = (stageLabelForRow(r) || '').trim(); if (lbl) stageByLabel.set(lbl, true); }
        const prev = filterStageLabel;
        const opts = [{ value: '', label: 'All Stages' }].concat([...stageByLabel.keys()].sort((a,b)=>a.localeCompare(b)).map(lbl => ({ value: lbl, label: lbl })));
        stageSel.innerHTML = opts.map(o => `<option value="${o.value}"${o.value===prev?' selected':''}>${o.label}</option>`).join('');
        if (!opts.find(o => o.value === prev)) filterStageLabel = '';
        filterStageId = '';
      } else {
        const stageMap = new Map();
        for (const r of rowsInScope) {
          const sid = r?.stage_live_id ?? r?.event_stage_live_id ?? r?.event?.stage_live_id;
          if (!sid) continue;
          const label = stageLookup.get(sid)?.name || stageLabelForRow(r) || 'Stage';
          if (!stageMap.has(sid)) stageMap.set(sid, label);
        }
        const prev = filterStageId;
        const opts = [{ value: '', label: 'All Stages' }].concat(
          [...stageMap.entries()].sort((a,b)=>String(a[1]).localeCompare(String(b[1]))).map(([sid,label]) => ({ value: sid, label }))
        );
        stageSel.innerHTML = opts.map(o => `<option value="${o.value}"${o.value===prev?' selected':''}>${o.label}</option>`).join('');
        if (!opts.find(o => o.value === prev)) filterStageId = '';
        filterStageLabel = '';
      }
    }

    // Event
    if (eventSel) {
      if (matterId == null) {
        const eventByLabel = new Map();
        for (const d of rowsInScope) {
          const stLbl = (stageLabelForRow(d) || '').trim();
          if (filterStageLabel && stLbl.toLowerCase() !== filterStageLabel.toLowerCase()) continue;
          const evLbl = (getEventLabelForRow(d) || '').trim();
          if (evLbl) eventByLabel.set(evLbl, true);
        }
        const prev = filterEventLabel;
        const opts = [{ value: '', label: 'All Events' }].concat(
          [...eventByLabel.keys()].sort((a,b)=>a.localeCompare(b)).map(lbl => ({ value: lbl, label: lbl }))
        );
        eventSel.innerHTML = opts.map(o => `<option value="${o.value}"${o.value===prev?' selected':''}>${o.label}</option>`).join('');
        if (!opts.find(o => o.value === prev)) filterEventLabel = '';
        filterEventId = '';
      } else {
        const eventMap = new Map();
        for (const d of rowsInScope) {
          const st = d?.stage_live_id ?? d?.event_stage_live_id ?? d?.event?.stage_live_id;
          if (filterStageId && st !== filterStageId) continue;
          const eid = d?.event_live_id ?? d?.event?.id;
          if (!eid) continue;
          const name = getEventLabelForRow(d) || '—';
          if (!eventMap.has(eid)) eventMap.set(eid, name);
        }
        const prev = filterEventId;
        const opts = [{ value: '', label: 'All Events' }].concat(
          [...eventMap.entries()].sort((a,b)=>String(a[1]).localeCompare(String(b[1]))).map(([id,name]) => ({ value: id, label: name }))
        );
        eventSel.innerHTML = opts.map(o => `<option value="${o.value}"${o.value===prev?' selected':''}>${o.label}</option>`).join('');
        if (!opts.find(o => o.value === prev)) filterEventId = '';
        filterEventLabel = '';
      }

      // ----- Defending Firm (internal-only) -----
      if (dfSel) {
        const rowsInScopeLocal = activeRows;

        if (matterId == null) {
          const dfByLabel = new Map();
          for (const d of rowsInScopeLocal) {
            const stLbl = (stageLabelForRow(d) || '').trim();
            const evLbl = (getEventLabelForRow(d) || '').trim();
            if (filterStageLabel && stLbl.toLowerCase() !== filterStageLabel.toLowerCase()) continue;
            if (filterEventLabel && evLbl.toLowerCase() !== filterEventLabel.toLowerCase()) continue;
            if (filterMatterNameLabel) {
              const nm = (getMatterNameForRow(d) || '').trim();
              if (!nm || nm.toLowerCase() !== filterMatterNameLabel.toLowerCase()) continue;
            }
            for (const nm of dfNamesForRow(d)) if (nm) dfByLabel.set(nm, true);
          }
          const prev = filterDfLabel;
          const opts = [{ value: '', label: 'All Defending Firms' }]
            .concat([...dfByLabel.keys()].sort((a,b)=>a.localeCompare(b)).map(lbl => ({ value: lbl, label: lbl })));
          dfSel.innerHTML = opts.map(o => `<option value="${o.value}"${o.value===prev?' selected':''}>${o.label}</option>`).join('');
          if (!opts.find(o => o.value === prev)) filterDfLabel = '';
          filterDfId = '';
        } else {
          // Single-matter: filter by DF id, honoring stage/event id filters
          const dfMap = new Map();
          for (const d of rowsInScopeLocal) {
            const stId = d?.stage_live_id ?? d?.event_stage_live_id ?? d?.event?.stage_live_id;
            if (filterStageId && stId !== filterStageId) continue;
            const evId = d?.event_live_id ?? d?.event?.id;
            if (filterEventId && evId !== filterEventId) continue;
            for (const f of getDfListForRow(d)) {
              const id = f?.id || null; if (!id) continue;
              const nm = (f?.name && String(f.name).trim()) || id;
              if (!dfMap.has(id)) dfMap.set(id, nm);
            }
          }
          const prev = filterDfId;
          const opts = [{ value: '', label: 'All Defending Firms' }]
            .concat([...dfMap.entries()].sort((a,b)=>String(a[1]).localeCompare(String(b[1]))).map(([id,label]) => ({ value: id, label })));
          dfSel.innerHTML = opts.map(o => `<option value="${o.value}"${o.value===prev?' selected':''}>${o.label}</option>`).join('');
          if (!opts.find(o => o.value === prev)) filterDfId = '';
          filterDfLabel = '';
        }
      }
    }

    ensureComboboxes();
    refreshComboboxOptions();
    applySearchableMode();
    updateFilterVisibility();
  }

  function wireFilterHandlers() {
    const ctrls = getFilterControls();
    matterNameSel = ctrls.matterNameSel;
    matterSel     = ctrls.matterSel;
    stageSel      = ctrls.stageSel;
    eventSel      = ctrls.eventSel;
    searchInput   = ctrls.searchInput;
    dfSel         = ctrls.dfSel;

    matterNameSel?.addEventListener('change', () => {
      filterMatterNameLabel = matterNameSel.value || '';
      // changing matter name should not override selected matter id, but filters should cascade
      rebuildNameCaches();
      populateFilters();
      applySearchableMode();
      refreshComboboxOptions();
      rebuildMonthEvents();
      renderAll();
    });

    matterSel?.addEventListener('change', () => {
      filterMatterId = matterSel.value || '';
      chooseActiveRows();

      // Clear dependent filters on matter-number change
      filterStageId = filterEventId = filterStageLabel = filterEventLabel = '';
      filterDfId = filterDfLabel = '';

      rebuildNameCaches();
      populateFilters();
      applySearchableMode();
      refreshComboboxOptions();
      rebuildMonthEvents();
      renderAll();
    });

    stageSel?.addEventListener('change', () => {
      if (matterId == null) {
        filterStageLabel = stageSel.value || ''; filterStageId = ''; filterEventLabel = ''; filterEventId = '';
      } else {
        filterStageId = stageSel.value || ''; filterStageLabel = ''; filterEventId = '';
      }
      populateFilters(); rebuildMonthEvents(); renderAll();
    });

    eventSel?.addEventListener('change', () => {
      if (matterId == null) { filterEventLabel = eventSel.value || ''; filterEventId = ''; }
      else { filterEventId = eventSel.value || ''; filterEventLabel = ''; }
      rebuildMonthEvents(); renderAll();
    });

    dfSel?.addEventListener('change', () => {
      if (matterId == null) { filterDfLabel = dfSel.value || ''; filterDfId = ''; }
      else { filterDfId = dfSel.value || ''; filterDfLabel = ''; }
      rebuildMonthEvents(); renderAll();
    });

    if (searchInput) {
      const debounce = (fn, ms = 200) => { let t; return (...args) => { clearTimeout(t); t = setTimeout(() => fn(...args), ms); }; };
      const onSearch = debounce(() => { searchTerm = (searchInput.value || '').trim().toLowerCase(); rebuildMonthEvents(); renderAll(); }, 200);
      searchInput.addEventListener('input', onSearch);
    }
  }

  // Month events
  let eventsByDay = [];
  function matchesFilters(row) {
    const rowStageId    = row.stage_live_id || row.event_stage_live_id || row?.event?.stage_live_id;
    const rowEventId    = row.event_live_id || row?.event?.id;
    const rowStageLabel = (stageLabelForRow(row) || '').trim();
    const rowEventLabel = (getEventLabelForRow(row) || '').trim();

    if (matterId == null) {
      if (filterStageLabel && rowStageLabel.toLowerCase() !== filterStageLabel.toLowerCase()) return false;
      if (filterEventLabel && rowEventLabel.toLowerCase() !== filterEventLabel.toLowerCase()) return false;
      if (filterMatterNameLabel) {
        const nm = (getMatterNameForRow(row) || '').trim().toLowerCase();
        if (nm !== filterMatterNameLabel.toLowerCase()) return false;
      }
    } else {
      if (filterStageId && rowStageId !== filterStageId) return false;
      if (filterEventId && rowEventId !== filterEventId) return false;
    }

    if (isInternal) {
      if (matterId == null && filterDfLabel) {
        const names = dfNamesForRow(row).map(s => s.toLowerCase());
        if (!names.includes(filterDfLabel.toLowerCase())) return false;
      }
      if (matterId != null && filterDfId) {
        const ids = getDfListForRow(row).map(f => f.id).filter(Boolean);
        if (!ids.includes(filterDfId)) return false;
      }
    }

    if (filterMatterId && getMatterIdForRow(row) !== filterMatterId) return false;

    if (searchTerm) {
      const haystack = [row.date_name, rowEventLabel, rowStageLabel, getMatterNameForRow(row), getMatterIdForRow(row)].filter(Boolean).join(' ').toLowerCase();
      if (!haystack.includes(searchTerm)) return false;
    }
    return true;
  }

  function rebuildMonthEvents() {
    const dim = daysInMonthUTC(viewYear, viewMonth);
    eventsByDay = Array.from({ length: dim + 1 }, () => []);
    const monthItems = [];
    for (const d of activeRows) {
      if (!matchesFilters(d)) continue;
      const ymd = parseYMD(d.date);
      if (!ymd || ymd.year !== viewYear || ymd.month !== viewMonth) continue;
      monthItems.push({ ymd, row: d });
    }

    monthItems.sort((a, b) => {
      const ar = a.row.rank || 0, br = b.row.rank || 0;
      if (ar !== br) return ar - br;
      const an = String(a.row.date_name || ''), bn = String(b.row.date_name || '');
      if (an !== bn) return an.localeCompare(bn);
      return String(getEventLabelForRow(a.row)).localeCompare(String(getEventLabelForRow(b.row)));
    });

    eventsByDay.forEach((_, i) => (eventsByDay[i] = []));
    for (const { ymd, row } of monthItems) {
      const eventName = getEventLabelForRow(row);
      const stageId   = row?.stage_live_id ?? row?.event_stage_live_id ?? row?.event?.stage_live_id ?? null;
      const stageName = stageLabelForRow(row);
      const dateLabel = row?.date_name?.trim() ? row.date_name : 'Date';
      const dateText  = `${dateLabel}: ${fmtMMDDYYYY(row.date)}`;
      const matterNum = getMatterIdForRow(row) ?? null;
      const matterName = (getMatterNameForRow(row) || '').trim();

      eventsByDay[ymd.day].push({
        header: dateText,
        eventLine: `Event: ${eventName || '—'}`,
        stageLine: `Stage: ${stageName || '—'}`,
        matterNameLine: matterName ? `Matter Name: ${matterName}` : '',
        matterNumberLine: matterNum ? `Matter Number: ${matterNum}` : '',
        stageId,
        eventLiveId: row?.event_live_id ?? row?.event?.id ?? null,
        dateLiveId: row?.id ?? null,
        raw: row,
      });
    }
  }

  // Modal
  function ensureModal() {
    if (modalEl) return modalEl;
    const overlay = el('div', 'wc-modal');
    Object.assign(overlay.style, { position: 'fixed', inset: '0', display: 'none', alignItems: 'center', justifyContent: 'center', background: 'rgba(0,0,0,0.5)', zIndex: 10000 });
    const dialog = el('div', 'wc-modal__content');
    Object.assign(dialog.style, { background: 'var(--bg-l3)', color: 'var(--text-light)', border: '1px solid var(--border-color)', borderRadius: '12px', width: 'min(720px, 92vw)', maxHeight: '80vh', overflow: 'auto', boxShadow: '0 10px 28px rgba(0,0,0,0.35)' });
    const header = el('div', 'wc-modal__header');
    Object.assign(header.style, { display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '12px 16px', borderBottom: '1px solid var(--border-color)', background: 'var(--bg-l2)' });
    const title = el('div', 'wc-modal__title', 'Day Agenda'); Object.assign(title.style, { fontWeight: '700' });
    const closeBtn = el('button', 'wc-modal__close', '×');
    Object.assign(closeBtn.style, { border: '1px solid var(--border-color)', background: 'var(--bg-l2)', color: 'var(--text-light)', borderRadius: '8px', fontSize: '16px', cursor: 'pointer', padding: '2px 8px' });
    closeBtn.addEventListener('mouseenter', () => closeBtn.style.borderColor = 'var(--primary)');
    const body = el('div', 'wc-modal__body'); Object.assign(body.style, { padding: '12px 16px', display: 'grid', gap: '8px' });
    header.appendChild(title); header.appendChild(closeBtn); dialog.appendChild(header); dialog.appendChild(body); overlay.appendChild(dialog); (document.getElementById('w_calendar') || document.body).appendChild(overlay);
    function onClose() { overlay.style.display = 'none'; body.innerHTML = ''; document.removeEventListener('keydown', onKey); }
    function onKey(e) { if (e.key === 'Escape') onClose(); }
    overlay.addEventListener('click', (e) => { if (e.target === overlay) onClose(); });
    closeBtn.addEventListener('click', onClose);
    modalEl = overlay; modalCloseFn = onClose; modalEl._titleEl = title; modalEl._bodyEl = body;
    modalEl.setAttribute('role', 'dialog'); modalEl.setAttribute('aria-modal', 'true'); modalEl.setAttribute('aria-label', 'Day Agenda');
    return modalEl;
  }

  function openDayModal(dayNum) {
    const modal = ensureModal();
    const body = modal._bodyEl; const titleEl = modal._titleEl;
    const dateStr = `${pad2(viewMonth + 1)}/${pad2(dayNum)}/${viewYear}`;
    titleEl.textContent = `Events on ${dateStr}`;
    const list = eventsByDay[dayNum] || [];
    if (!list.length) body.innerHTML = '<div class="wc-empty">No events for this day.</div>';
    else list.forEach(evt => body.appendChild(buildEventCard(evt)));
    modal.style.display = 'flex';
    document.addEventListener('keydown', (e) => { if (e.key === 'Escape') modalCloseFn?.(); });
  }

  // Calendar rendering
  function buildEventCard(evt) {
    const a = el('a', 'wc-event');
    a.href = '#';
    a.dataset.stageId     = evt.stageId || '';
    a.dataset.eventLiveId = evt.eventLiveId || '';
    a.dataset.dateLiveId  = evt.dateLiveId || '';

    const resolvedMatterId   = getMatterIdForRow(evt.raw) ?? matterId ?? null;
    const resolvedMatterName = (getMatterNameForRow(evt.raw) || '').trim();

    // --- TOOLTIP ORDER: Matter Name → Matter Number → Date → Event → Stage
    const tooltipLines = [
      resolvedMatterName ? `Matter Name: ${resolvedMatterName}` : '',
      resolvedMatterId ? `Matter Number: ${resolvedMatterId}` : '',
      evt.header,                    // e.g. "Submission Date: 10/09/2025"
      evt.eventLine,
      evt.stageLine,
    ].filter(Boolean);
    const tooltip = tooltipLines.join('\n');
    a.title = tooltip;
    a.setAttribute('aria-label', tooltipLines.join(' • '));

    // --- VISIBLE TEXT ORDER IN CARD:
    // Matter Name → Matter Number → Date → Event → Stage
    const txt = el('div', 'wc-event__txt');
    if (resolvedMatterName || evt.matterNameLine) {
      txt.appendChild(el('div', 'wc-event__meta',
        evt.matterNameLine || `Matter Name: ${resolvedMatterName}`));
    }
    if (resolvedMatterId || evt.matterNumberLine) {
      txt.appendChild(el('div', 'wc-event__meta',
        evt.matterNumberLine || `Matter Number: ${resolvedMatterId}`));
    }
    // keep the date styled as title but placed after matter name
    txt.appendChild(el('div', 'wc-event__title', evt.header));
    txt.appendChild(el('div', 'wc-event__meta',  evt.eventLine));
    txt.appendChild(el('div', 'wc-event__meta',  evt.stageLine));
    a.appendChild(txt);

    a.addEventListener('click', (e) => {
      e.preventDefault();
      if (resolvedMatterId) SlateFunctions.triggerEvent?.('openMatter', resolvedMatterId);
    });

    return a;
  }


  function dayCell(dayNum, muted = false) {
    const isCurrentMonth = (viewYear === TODAY_Y && viewMonth === TODAY_M && dayNum === TODAY_D);
    const cell = el('div', `wc-day${muted ? ' is-muted' : ''}`);
    cell.appendChild(el('span', 'wc-day__num', String(dayNum)));

    if (!muted && isCurrentMonth) { cell.classList.add('is-today'); cell.setAttribute('data-today', '1'); cell.setAttribute('tabindex', '-1'); }
    if (muted) return cell;

    const list = eventsByDay[dayNum] || [];
    const listWrap = el('div', 'wc-day__list');
    cell.appendChild(listWrap);

    if (list.length) listWrap.appendChild(buildEventCard(list[0]));
    if (list.length > 1) {
      const hiddenCount = list.length - 1;
      const chip = el('button', 'wc-chip', `View more (${hiddenCount})`);
      chip.addEventListener('click', (e) => {
        e.preventDefault();
        openDayModal(dayNum);
        SlateFunctions.triggerEvent?.('openDayAgenda', JSON.stringify({ matterId, year: viewYear, month: viewMonth + 1, day: dayNum }));
      });
      listWrap.appendChild(chip);
    }
    return cell;
  }

  const monthNames = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  function setTitle(m, y) { const titleText = $('.wc-title-text'); if (titleText) titleText.textContent = `${monthNames[m].toUpperCase()} ${y}`; setMonthInput(y, m); }

  function renderCalendar(month, year) {
    setTitle(month, year);
    const grid = $('.wc-calendar__grid'); if (!grid) return;
    grid.innerHTML = '';
    const startOffset = firstWeekdayIndexMondayFirstUTC(year, month);
    const dim = daysInMonthUTC(year, month);
    const dimPrev = daysInPrevMonthUTC(year, month);

    const frag = document.createDocumentFragment();
    for (let i = startOffset - 1; i >= 0; i--) frag.appendChild(dayCell(dimPrev - i, true));
    for (let d = 1; d <= dim; d++) frag.appendChild(dayCell(d, false));
    const total = startOffset + dim;
    const tail = (7 - (total % 7)) % 7;
    for (let d = 1; d <= tail; d++) frag.appendChild(dayCell(d, true));
    grid.appendChild(frag);
  }

  // Today
  function focusTodayCell() {
    if (viewYear !== TODAY_Y || viewMonth !== TODAY_M) return;
    const cell = $('.wc-day.is-today'); if (!cell) return;
    cell.classList.remove('is-spotlight'); void cell.offsetHeight; cell.classList.add('is-spotlight'); cell.focus({ preventScroll: false });
  }
  function wireTodayButton() {
    $('.wc-today-btn')?.addEventListener('click', () => {
      viewYear = TODAY_Y; viewMonth = TODAY_M;
      rebuildMonthEvents(); renderAll(); focusTodayCell(); closePicker();
    });
  }

  // Picker
  function wireMonthPicker() {
    const inp = $('.wc-monthpick'); if (!inp) return;
    setMonthInput(viewYear, viewMonth);
    inp.addEventListener('change', () => {
      const m = /^(\d{4})-(\d{2})$/.exec(inp.value); if (!m) return;
      viewYear = +m[1]; viewMonth = +m[2] - 1;
      rebuildMonthEvents(); renderAll(); closePicker();
    });
    const open = () => openPicker(inp);
    inp.addEventListener('click', (e) => { e.preventDefault(); open(); });
    inp.addEventListener('focus', open);
  }

  function buildPicker() {
    if (pickerEl) return pickerEl;
    const pop = el('div', 'wc-mypicker');
    Object.assign(pop.style, { position: 'absolute', zIndex: 9999, background: 'rgba(26,47,88,0.98)', border: '1px solid var(--primary)', borderRadius: '12px', padding: '10px', boxShadow: '0 10px 28px rgba(0,0,0,0.35)', width: '320px', color: 'var(--text-light)' });

    const hdr = el('div', 'myp-hdr', `
      <button class="myp-prev" aria-label="Previous decade">«</button>
      <div class="myp-range" aria-live="polite"></div>
      <button class="myp-next" aria-label="Next decade">»</button>
    `);
    Object.assign(hdr.style, { display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '8px' });
    hdr.querySelectorAll('button').forEach(b => { Object.assign(b.style, { background: 'var(--bg-l2)', color: 'var(--text-light)', border: '1px solid var(--border-color)', borderRadius: '8px', padding: '4px 8px', cursor: 'pointer' }); b.addEventListener('mouseenter', () => b.style.borderColor = 'var(--primary)'); b.addEventListener('mouseleave', () => b.style.borderColor = 'var(--border-color)'); });

    const yg = el('div', 'myp-years'); Object.assign(yg.style, { display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: '6px', marginBottom: '10px' });
    const mh = el('div', 'myp-month-h', ''); mh.style.fontSize = '12px'; mh.style.color = 'var(--text-meta)'; mh.style.margin = '2px 0 6px';
    const mg = el('div', 'myp-months'); mg.style.display = 'grid'; mg.style.gridTemplateColumns = 'repeat(4, 1fr)'; mg.style.gap = '6px';

    pop.appendChild(hdr); pop.appendChild(yg); pop.appendChild(mh); pop.appendChild(mg);
    hdr.querySelector('.myp-prev').addEventListener('click', () => { pickerStartYear -= 10; renderYears(); });
    hdr.querySelector('.myp-next').addEventListener('click', () => { pickerStartYear += 10; renderYears(); });

    function renderYears() {
      const start = pickerStartYear ?? (viewYear - 7);
      pickerStartYear = start;
      const years = Array.from({ length: 15 }, (_, i) => start + i);
      yg.innerHTML = '';
      hdr.querySelector('.myp-range').textContent = `${years[0]}–${years[years.length - 1]}`;
      years.forEach(y => {
        const btn = el('button', 'yp-year', String(y));
        Object.assign(btn.style, { background: (y === pickerSelectedYear) ? 'var(--primary)' : 'var(--bg-l2)', color: (y === pickerSelectedYear) ? '#0b183a' : 'var(--text-light)', border: '1px solid var(--border-color)', borderRadius: '8px', padding: '6px 0', cursor: 'pointer', fontWeight: (y === pickerSelectedYear) ? '700' : '500' });
        btn.addEventListener('mouseenter', () => btn.style.borderColor = 'var(--primary)');
        btn.addEventListener('mouseleave', () => btn.style.borderColor = 'var(--border-color)');
        btn.addEventListener('click', () => { pickerSelectedYear = y; renderYears(); renderMonths(); });
        yg.appendChild(btn);
      });
    }

    function renderMonths() {
      mg.innerHTML = '';
      mh.textContent = `Months in ${pickerSelectedYear}`;
      ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'].forEach((label, idx) => {
        const active = pickerSelectedYear === viewYear && idx === viewMonth;
        const btn = el('button', 'mp-month', label);
        Object.assign(btn.style, { background: active ? 'var(--primary)' : 'var(--bg-l2)', color: active ? '#0b183a' : 'var(--text-light)', border: '1px solid var(--border-color)', borderRadius: '8px', padding: '8px 0', cursor: 'pointer', fontWeight: active ? '700' : '500' });
        btn.addEventListener('mouseenter', () => btn.style.borderColor = 'var(--primary)');
        btn.addEventListener('mouseleave', () => btn.style.borderColor = 'var(--border-color)');
        btn.addEventListener('click', () => { viewYear = pickerSelectedYear; viewMonth = idx; setMonthInput(viewYear, viewMonth); rebuildMonthEvents(); renderAll(); closePicker(); });
        mg.appendChild(btn);
      });
    }

    pop.renderYears = renderYears; pop.renderMonths = renderMonths;
    pop.setAttribute('role', 'dialog'); pop.setAttribute('aria-label', 'Pick year and month');
    pickerEl = pop; return pop;
  }

  function positionPopover(pop, anchor) {
    const a = anchor.getBoundingClientRect();
    const scrollY = window.scrollY || document.documentElement.scrollTop || 0;
    const scrollX = window.scrollX || document.documentElement.scrollLeft || 0;
    pop.style.top = `${a.bottom + scrollY + 6}px`;
    pop.style.left = `${a.left + scrollX}px`;
  }

  function openPicker(anchor) {
    const pop = buildPicker();
    if (!pop.isConnected) document.body.appendChild(pop);
    pickerSelectedYear = viewYear; pickerStartYear = viewYear - 7;
    pop.renderYears(); pop.renderMonths();
    positionPopover(pop, anchor);
    document.addEventListener('click', onDocClick, { capture: true });
    document.addEventListener('keydown', onDocKey);
    window.addEventListener('resize', onResize);
    window.addEventListener('scroll', onResize, true);
  }
  function closePicker() {
    if (pickerEl?.isConnected) pickerEl.remove();
    document.removeEventListener('click', onDocClick, { capture: true });
    document.removeEventListener('keydown', onDocKey);
    window.removeEventListener('resize', onResize);
    window.removeEventListener('scroll', onResize, true);
  }
  function onDocClick(e) { if (!pickerEl?.contains(e.target) && e.target !== $('.wc-monthpick')) closePicker(); }
  function onDocKey(e) { if (e.key === 'Escape') closePicker(); }
  function onResize() { if (pickerEl?.isConnected) positionPopover(pickerEl, $('.wc-monthpick')); }

    // Timeline
    const UPCOMING_LIMIT = 5;
    function computeUpcoming(limit = UPCOMING_LIMIT) {
      const nowTs = Date.UTC(TODAY_Y, TODAY_M, TODAY_D);
      return activeRows
        .filter(d => matchesFilters(d) && toUTCTs(d.date) >= nowTs)
        .sort((a, b) => toUTCTs(a.date) - toUTCTs(b.date))
        .slice(0, limit);
    }

    function ensureTimelineContainer() {
      let tl = document.querySelector('.wc-timeline'); if (tl) return tl;
      const header = document.querySelector('.wc-calendar__header');
      const calendar = document.querySelector('.wc-calendar');
      const grid = document.querySelector('.wc-calendar__grid');
      tl = el('div', 'wc-timeline', `
        <div class="wc-timeline__title">UPCOMING DATES</div>
        <div class="wc-timeline__axis">
          <div class="wc-timeline__line"></div>
          <div class="wc-timeline__now" style="left:0;"></div>
        </div>
        <div class="wc-timeline__empty wc-empty" style="display:none;"></div>
      `);
      if (header) header.insertAdjacentElement('afterend', tl);
      else if (calendar && grid) calendar.insertBefore(tl, grid);
      else if (calendar) calendar.appendChild(tl);
      else document.body.appendChild(tl);
      return tl;
    }

    function renderTimeline() {
      const tl = ensureTimelineContainer();
      if (!tl) return;

      const axis  = tl.querySelector('.wc-timeline__axis');
      const empty = tl.querySelector('.wc-timeline__empty');

      axis.style.position = axis.style.position || 'relative';
      axis.querySelectorAll('.wc-timeline__dot, .wc-timeline__label, .wc-timeline__stem').forEach(n => n.remove());

      const items = computeUpcoming();
      if (!items || !items.length) {
        empty.style.display = 'block';
        empty.textContent = 'No upcoming dates';
        return;
      }
      empty.style.display = 'none';

      const width = axis.clientWidth || axis.getBoundingClientRect().width || 600;
      const pad = 16;
      const leftEdge  = pad;
      const rightEdge = Math.max(leftEdge + 1, width - pad);
      const n = items.length;
      const targets = n === 1
        ? [(leftEdge + rightEdge) / 2]
        : Array.from({ length: n }, (_, i) => leftEdge + (rightEdge - leftEdge) * (i / (n - 1)));

      const axisY  = 28;
      const stemH  = 18;
      const gapY   = 8;
      const MIN_GAP = 12; // px between cards

      // Build labels first to measure width
      const nodes = items.map((d, i) => {
        const mid = getMatterIdForRow(d) ?? matterId ?? null;
        const mname = (getMatterNameForRow(d) || '').trim();

        const label = el('a', 'wc-timeline__label', `
          ${mname ? `<div><strong>Matter Name:</strong> ${mname}</div>` : ''}
          ${mid ? `<div><strong>Matter Number:</strong> ${mid}</div>` : ''}
          <div><strong>${d?.date_name || 'Date'}:</strong> ${fmtMMDDYYYY(d?.date)}</div>
          <div><strong>Event:</strong> ${getEventLabelForRow(d) || '—'}</div>
          <div><strong>Stage:</strong> ${stageLabelForRow(d) || '—'}</div>
        `);

        label.href = '#';
        label.setAttribute('data-matter-id', mid || '');
        Object.assign(label.style, { position: 'absolute', zIndex: '3', pointerEvents: 'auto', cursor: 'pointer', visibility: 'hidden' });
        label.addEventListener('click', (e) => {
          e.preventDefault();
          if (mid) SlateFunctions.triggerEvent?.('openMatter', mid);
        });
        axis.appendChild(label);

        const w = Math.max(140, Math.round(label.getBoundingClientRect().width || 180));
        const target = Math.min(Math.max(targets[i], leftEdge + w / 2), rightEdge - w / 2);

        return { i, data: d, label, w, target, x: target, matterId: mid, matterName: mname };
      });

      // Resolve overlaps (left→right push, then right→left clamp)
      nodes.sort((a, b) => a.target - b.target);

      // initial clamp
      nodes.forEach(n => {
        n.x = Math.max(leftEdge + n.w / 2, Math.min(n.target, rightEdge - n.w / 2));
      });

      // forward pass: ensure min gap
      for (let i = 1; i < nodes.length; i++) {
        const prev = nodes[i - 1], cur = nodes[i];
        const minX = prev.x + prev.w / 2 + MIN_GAP + cur.w / 2;
        if (cur.x < minX) cur.x = minX;
      }

      // backward pass: pull back inside right boundary and re-enforce gaps
      for (let i = nodes.length - 1; i >= 0; i--) {
        const cur = nodes[i];
        if (cur.x + cur.w / 2 > rightEdge) cur.x = rightEdge - cur.w / 2;
        if (i > 0) {
          const prev = nodes[i - 1];
          const minX = prev.x + prev.w / 2 + MIN_GAP + cur.w / 2;
          if (cur.x < minX) cur.x = minX;
        }
      }

      // place everything
      nodes.forEach((n) => {
        const px = n.x;

        const dot = el('div', 'wc-timeline__dot');
        Object.assign(dot.style, { position: 'absolute', zIndex: '2', left: `${px}px` });
        dot.setAttribute('tabindex', '0');
        const tLines = [
          n.matterName ? `Matter Name: ${n.matterName}` : '',
          `${fmtMMDDYYYY(n.data?.date)} — ${n.data?.date_name || 'Date'}`,
          getEventLabelForRow(n.data) ? `Event: ${getEventLabelForRow(n.data)}` : '',
          stageLabelForRow(n.data) ? `Stage: ${stageLabelForRow(n.data)}` : '',
          n.matterId ? `Matter Number: ${n.matterId}` : '',
        ].filter(Boolean);
        dot.title = tLines.join(' • ');        

        const stem = el('div', 'wc-timeline__stem');
        Object.assign(stem.style, { position: 'absolute', zIndex: '1', left: `${px}px`, top: `${axisY}px`, height: `${stemH}px` });

        axis.appendChild(dot);
        axis.appendChild(stem);

        n.label.style.visibility = 'visible';
        n.label.style.left = `${px}px`;
        n.label.style.top  = `${axisY + stemH + gapY}px`;
        n.label.style.transform = 'translateX(-50%)';
      });

      if ((axis.clientWidth || axis.getBoundingClientRect().width || 0) < 2) {
        requestAnimationFrame(renderTimeline);
      }
    }

    // Reset filters
    function resetFiltersToDefault() {
      filterMatterNameLabel = '';
      filterMatterId = filterStageId = filterEventId = '';
      filterStageLabel = filterEventLabel = '';
      filterDfId = ''; filterDfLabel = '';
      searchTerm = '';

      const { matterNameSel, matterSel, stageSel, eventSel, searchInput, dfSel } = getFilterControls();
      if (searchInput) searchInput.value = '';

      if (matterNameSel) matterNameSel.value = '';
      if (matterSel)     matterSel.value     = '';
      if (stageSel)      stageSel.value      = '';
      if (eventSel)      eventSel.value      = '';
      if (dfSel)         dfSel.value         = '';

      // recompute rows first, then rebuild filter option lists
      chooseActiveRows();
      populateFilters();
      applySearchableMode();
      refreshComboboxOptions();
      updateFilterVisibility();
      rebuildMonthEvents();
      renderAll();
    }

    function wireResetButton() {
      document.querySelector('.wc-reset-btn')?.addEventListener('click', (e) => { e.preventDefault(); resetFiltersToDefault(); });
    }

    // Navigation
    function wireNav() {
      $('.wc-nav--prev')?.addEventListener('click', () => {
        viewMonth = viewMonth > 0 ? viewMonth - 1 : 11;
        if (viewMonth === 11) viewYear--;
        rebuildMonthEvents(); renderAll(); closePicker();
      });
      $('.wc-nav--next')?.addEventListener('click', () => {
        viewMonth = viewMonth < 11 ? viewMonth + 1 : 0;
        if (viewMonth === 0) viewYear++;
        rebuildMonthEvents(); renderAll(); closePicker();
      });
    }

    // Adaptive card fitting (apply .is-overflow marker only if overflowing)
    function fitCardsToCells() {
      document.querySelectorAll('.wc-day:not(.is-muted)').forEach((day) => {
        const list = day.querySelector('.wc-day__list');
        const card = list?.querySelector('.wc-event');
        day.classList.remove('is-overflow');
        if (!list || !card) return;
        if (card.offsetHeight > list.clientHeight) {
          day.classList.add('is-overflow');
        }
      });
    }

    // Orchestrator
    function renderAll() {
      renderCalendar(viewMonth, viewYear);
      renderTimeline();
      fitCardsToCells();
      requestAnimationFrame(fitCardsToCells);
      if (document.fonts?.ready) document.fonts.ready.then(() => requestAnimationFrame(fitCardsToCells));
    }

    function init() {
      watchSlateState();
      setTimeout(() => {
        readSlateState();
        populateFilters();
        wireBackButton();
        wireNav();
        wireTodayButton();
        wireMonthPicker();
        wireFilterHandlers();
        wireResetButton();
        ensureTimelineContainer();

        rebuildMonthEvents();
        renderAll();

        if (viewYear === TODAY_Y && viewMonth === TODAY_M) setTimeout(focusTodayCell, 0);

        window.addEventListener('resize', () => requestAnimationFrame(fitCardsToCells));
        const grid = document.querySelector('.wc-calendar__grid');
        if (window.MutationObserver && grid) {
          new MutationObserver(() => requestAnimationFrame(fitCardsToCells))
            .observe(grid, { childList: true, subtree: true });
        }
      }, 50);
    }

    if (document.readyState !== 'loading') init();
    else document.addEventListener('DOMContentLoaded', init);
  })();

