w_in_app_notification.custom.collectNoti.functionBody:
const prev = Array.isArray({{v_notifications_to_be_marked_as_read}}) ? {{v_notifications_to_be_marked_as_read}} : [];

const payload = {{slEventValue}} || {};
const list = Array.isArray(payload.notifications) ? payload.notifications : null;

const single = payload.notification || (!list && payload) || null;

const keyOf = (n) => n?.rid
  ? `rid:${n.rid}`
  : (n?.typeId && n?.primaryKey?.id)
    ? `pk:${n.typeId}:${n.primaryKey.id}`
    : null;

if (list) {
  const dedup = [];
  const seen = new Set();
  for (const n of list) {
    const k = keyOf(n);
    if (k && !seen.has(k)) { seen.add(k); dedup.push(n); }
  }
  return dedup;              
}

if (single) {
  const k = keyOf(single);
  if (!k) return prev;
  if (prev.some(x => keyOf(x) === k)) return prev;
  return [...prev, single]; 
}

return prev;

const prev = Array.isArray({{v_notifications_to_be_marked_as_unread}}) ? {{v_notifications_to_be_marked_as_unread}} : [];

const payload = {{slEventValue}} || {};
const list = Array.isArray(payload.notifications) ? payload.notifications : null;
const single = payload.notification || (!list && payload) || null;

const keyOf = (n) => n?.rid
  ? `rid:${n.rid}`
  : (n?.typeId && n?.primaryKey?.id)
    ? `pk:${n.typeId}:${n.primaryKey.id}`
    : null;

if (list) {
  const dedup = [];
  const seen = new Set();
  for (const n of list) {
    const k = keyOf(n);
    if (k && !seen.has(k)) { seen.add(k); dedup.push(n); }
  }
  return dedup;     
}

if (single) {
  const k = keyOf(single);
  if (!k) return prev;
  if (prev.some(x => keyOf(x) === k)) return prev;
  return [...prev, single]; 
}

return prev;

