  },
  "type": "terms"
}] :
[];

const actionItemsTotal = {{q_count_action_item_per_matter.result.[0].aggregations.total_count.buckets}};
const actionItemsCompleted = {{q_count_action_item_completed_per_matter.result.[0].aggregations.total_count.buckets}};

if (!actionItemsTotal || !actionItemsCompleted) {
  return {}
}

function bucketArrayToObject(arr) {
  const obj = {};
  arr.forEach(item => {
    obj[item.key] = item.doc_count;
  });
  return obj;
}

// Elements to compute percentage
const totalItemsAsDenominators = bucketArrayToObject(actionItemsTotal)
const completedAsNumerators = bucketArrayToObject(actionItemsCompleted)
const completionPercentage = {}

Object.keys(totalItemsAsDenominators).forEach(key => {
  completionPercentage[key] = key in completedAsNumerators ?
    Math.round(100 * completedAsNumerators[key]/totalItemsAsDenominators[key]) :
    0;
})

return completionPercentage

