const propertyId = {{f_ontology_props_matter.ridMap.name}}
const sortOrder = 'ASCENDING'
const objectTypePrefix = {{v_object_type_prefix}}
const objectIdMatter = {{v_object_id_matter}}
const objectIdFirm = {{v_object_id_company}}

const nameSearch = {{w_case_name_filter.searchText}}

const filters = []

let queryBaseObjectSet = baseObjectSet(`${objectTypePrefix}${objectIdMatter}`)

if (nameSearch) {
  const searchableProperties = ["name"]
  filters.push(multiMatchFilter({ query: nameSearch, properties: searchableProperties }))
}

const currentUserFirmId = {{s_current_user_person_firm.data.id.[0]}} ?? null
const isUserFromExternalLawFirm = {{s_current_user_person_firm.data.outside_counsel.[0]}} ?? null

const relationIdMatterAssignmentMatter = {{v_relation_id_matter_assignment_matter}}
const relationIdMatterAssignmentCompany = {{v_relation_id_matter_assignment_law_firm}}

const outsideCounsel = []
const isExternalUserLoadingFirmAssignment = isUserFromExternalLawFirm && currentUserFirmId
if (isExternalUserLoadingFirmAssignment) {
  outsideCounsel.push(currentUserFirmId)
}

if (outsideCounsel.length) {
  const filterObjectSet = filteredObjectSet(exactMatchFilter(outsideCounsel, "id"), baseObjectSet(`${objectTypePrefix}${objectIdFirm}`))
  const sourceAssignmentCompanySearchAroundSet = searchAroundObjectSet({ objectSet: filterObjectSet, relationSide: "SOURCE", relationId: `${objectTypePrefix}${relationIdMatterAssignmentCompany}` })
  let assignFilteredObjectSet = sourceAssignmentCompanySearchAroundSet
  if (isExternalUserLoadingFirmAssignment) {
    assignFilteredObjectSet = filteredObjectSet(exactMatchFilter(["Defending Firm", "Early Starter Firm"], "assignment_type"), assignFilteredObjectSet)
  }
  queryBaseObjectSet = searchAroundObjectSet({ objectSet: assignFilteredObjectSet, relationSide: "TARGET", relationId: `${objectTypePrefix}${relationIdMatterAssignmentMatter}` })
}

const query = {
  objectSet: filteredObjectSet(andFilter(filters), queryBaseObjectSet),
  objectSetContext: {},
  pageSize: 9000,
  propertySet: {
    selected: {
      propertySelection: {
        propertyTypeRid: {
          propertyTypeRids: [{{f_ontology_props_matter.ridMap.name}}],
          type: "propertyTypeRids",
        },
        type: "propertyTypeRid",
      },
      type: "propertySelection",
    },
    type: "selected"
  },
  resultOrdering: {
    propertyValue: {
      propertyOrdering: [
        {
          singleObjectTypeProperty: {
            propertyTypeRid: propertyId,
