/* ---------- helpers & CA-lawsuit / role gating ---------- */
const toBool = (v) => {
  if (typeof v === 'boolean') return v;
  if (typeof v === 'number') return v !== 0;
  if (typeof v === 'string') return ['1','true','yes','y'].includes(v.trim().toLowerCase());
  return false;
};

const isSnfType = (t = '') => {
  const x = String(t).trim();
  return x === 'SNF' || x === 'Statutory Notice Firm' || x === 'Statutory Notice Counsel';
};

const isCaLawsuitRaw =
  toBool(properties.ca_civil_penalty_notice_flag) && toBool(properties.ca_lawsuit_flag);

const rolesForCurrentFirm =
  (assignmentMap[properties.id]?.byFirm?.[currentUserFirmId]?.roles || []).map(r => r.assignmentType);

// Explicit role flags (SNF parity with DC)
const isDF  = rolesForCurrentFirm.includes("Defending Firm");
const isESF = rolesForCurrentFirm.includes("Early Starter Firm");
const isDC  = rolesForCurrentFirm.includes("Discovery Counsel");
const isSNF = rolesForCurrentFirm.includes("Statutory Notice Firm");

// Action-capability rollups (SNF behaves like DC)
const canDoDFActionsAsExternalFirm = isDF;
const canDoDCActionsAsExternalFirm = isDC || isSNF;
const canDoESFActionsAsExternalFirm = isESF;

const isUserFirmAssignedWithActionRole =
  canDoDFActionsAsExternalFirm || canDoDCActionsAsExternalFirm || canDoESFActionsAsExternalFirm;

/** Effective read-only:
 * - Any global read-only role, OR
 * - External user on a CA-lawsuit where their firm is NOT DF/ESF/DC/SNF
 */
const effectiveReadOnly =
  !!hasReadOnlyRole ||
  (isUserFromExternalLawFirm && isCaLawsuitRaw && !isUserFirmAssignedWithActionRole);

/* ---------- human-friendly lookups ---------- */
const caseHandlerIndex = properties?.case_handler ? caseHandlerDetails.raw.indexOf(properties.case_handler) : null;
const caseHandlerName = properties?.case_handler ? (caseHandlerDetails.display[caseHandlerIndex] ?? '-') : '-';
const legalAssistantIndex = properties?.legal_assistant ? legalAssistantDetails.raw.indexOf(properties.legal_assistant) : null;
const legalAssistantName = properties?.legal_assistant ? (legalAssistantDetails.display[legalAssistantIndex] ?? '-') : '-';

/* ---------- role-derived action capabilities ---------- */
properties.can_do_df_actions_as_external_firm = canDoDFActionsAsExternalFirm;

// Internal users can always act (unless read-only flag says otherwise).
// External: DF/DC/SNF can act; ESF follows ESF rules (as per parity decisions).
properties.can_do_df_actions = (!hasReadOnlyRole && isInternalUser) || canDoDFActionsAsExternalFirm;
properties.can_do_dc_actions = (!hasReadOnlyRole && isInternalUser) || canDoDCActionsAsExternalFirm; // DC or SNF
properties.can_do_esf_actions = (!hasReadOnlyRole && isInternalUser) || canDoESFActionsAsExternalFirm;

/* ---------- derived flags used by the opened view ---------- */
properties.has_been_released = !!properties.evaluation_released_by;
properties.has_disposition_summary = !!properties.final_disposition_completed_at;
properties.has_matter_disposition = !!properties.matter_disposition_updated_at;

/* Assignee requirement warning */
properties.show_assignee_requirement_warning = isUserFromExternalLawFirm
