properties.show_matter_settlement_requirement_warning = (isInternalUser || isDF)
  && !properties.has_disposition_summary
  && ((isInternalUser && (properties.assignment_status === 'Open')) || (properties.assignment_status === 'In Progress'));

properties.show_matter_closing_requirement_warning = (isInternalUser || isDF)
  && (!properties.has_disposition_summary || !properties.has_matter_disposition)
  && ((isInternalUser && (properties.assignment_status === 'Open')) || (properties.assignment_status === 'In Progress') || (properties.assignment_status === 'Settled'));

/* ---------- display fields ---------- */
properties.case_handler_name = caseHandlerName ?? '-';
properties.legal_assistant_name = legalAssistantName;
