properties.total_spend = formatCurrency(properties.total_spend);
properties.serve_notice_date = formatDate(properties.serve_notice_date);
properties.pre_lit_repurchase_offer = booleanText(properties.pre_lit_repurchase_offer);
properties.opposing_firm_names = displayLists(properties.opposing_firm_names);

/* ---- primary_assignee: remove SNF from display ---- */
(() => {
  // Build a name set for firms that have any SNF-ish role on this matter
  const byFirm = assignmentMap[properties.id]?.byFirm || {};
  const snfFirmNames = new Set(
    Object.values(byFirm)
      .filter(f => (f.roles || []).some(r => isSnfType(r.assignmentType)))
      .map(f => f.name)
      .filter(Boolean)
  );

  // Filter POCs to exclude those tied to SNF firms (by firmName match)
  const rawPocs = mainPocs?.[properties.id] || [];
  const filteredPocs = rawPocs.filter(p => !snfFirmNames.has(p.firmName));

  properties.primary_assignee = primaryAssigneeDisplay(filteredPocs);
})();

properties.vehicle_model = properties.vehicle_model ?? '-';
properties.vehicle_model_year = properties.vehicle_model_year ?? '-';
properties.primary_vin = properties.primary_vin ?? '-';
properties.action_type = properties.action_type ?? '-';

/* ---------- assignmentDetails (force show firms for CA-lawsuit, read-only externals) ---------- */
(() => {
