const filters = []

const isNotEmpty = (value) => value && value.length

if (searchTerm) {
  const searchableProperties = ["name", "id", "legal_assistant_name", "case_handler_name", "opposing_firm_names", "venue_name", "venue_state", "venue_county", "assigned_firm_names_1"]
  filters.push(multiMatchFilter({ query: searchTerm, properties: searchableProperties }))
}

for (const filter of exactMatchFilters) {
  if (isNotEmpty(filter.values)) {
    filters.push(exactMatchFilter(filter.values, filter.property))
  }
}

for (const filter of booleanFilters) {
  if (isNotEmpty(filter.values)) {
    if (filter.values.includes(null)) {
      const notNullValues = filter.values.filter(value => value !== null)
      const currentFilters = []

      if (isNotEmpty(notNullValues)) {
        currentFilters.push(exactMatchFilter(notNullValues, filter.property))
      }

      currentFilters.push(notFilter(hasPropertyFilter(filter.property)))
      filters.push(orFilter(currentFilters))
    } else {
      filters.push(exactMatchFilter(filter.values, filter.property))
    }
  }
}


for (const range of dateRangesFilters) {
  if (isNotEmpty(range.from) && isNotEmpty(range.to)) {
    filters.push(rangeFilter(range.field, { lte: range.to, gte: range.from }))
  }
}

for (const range of numberRangesFilters) {
  if (!isNaN(range.from) || !isNaN(range.to)) {
    filters.push(rangeNumberFilter(range.field, { gte: range.from, lte: range.to }))
  }
}

