  if (isExternalUserLoadingFirmAssignment) {
    assignFilteredObjectSet = filteredObjectSet(exactMatchFilter(["Defending Firm", "Early Starter Firm"], "assignment_type"), assignFilteredObjectSet)
  }
  const targetMatterAssignmentMatterSearchAroundSet = searchAroundObjectSet({ objectSet: assignFilteredObjectSet, relationSide: "TARGET", relationId: `${objectTypePrefix}${relationIdMatterAssignmentMatter}` })
  matterObjectSets.push(targetMatterAssignmentMatterSearchAroundSet)
}

