    const upcomingTrialDatesRange = addDurationToToday(1, "years")
    const dateFilter = rangeFilter("trial_date", { lte: upcomingTrialDatesRange.from, gte: upcomingTrialDatesRange.to })
    const statusFilter = exactMatchFilter(["Open", "In Progress"], "assignment_status")
    const upcomingTrialFilters = andFilter([dateFilter, statusFilter])
    filters.push(upcomingTrialFilters)
}


if(preFilterSelected === "pre_lit_cases") {
    const assignedAtAgo = subtractDurationFromTodayUnix(3, "years")
    const assignedAtFilter = rangeFilter("assigned_at", { lte: assignedAtAgo.to, gte: assignedAtAgo.from })
    const statusFilter = exactMatchFilter(["Open", "In Progress"], "assignment_status")
    const preLitFilter = exactMatchFilter([true], "pre_lit_demand")
    const preLitCasesFilters = andFilter([assignedAtFilter, statusFilter, preLitFilter])
    filters.push(preLitCasesFilters)
}

if(preFilterSelected === "dormant_cases") {
    const timestamp60DaysAgo = subtractDurationFromTodayUnix(35, "days")

    const statusFilter = exactMatchFilter(["Open", "In Progress"], "assignment_status")
    const mattersAssignedFilter = rangeFilter("assigned_at", {lte: timestamp60DaysAgo.from})
    const openMatters = filteredObjectSet(andFilter([mattersAssignedFilter, statusFilter]), baseObjectSet(`${objectTypePrefix}${objectIdMatter}`))


    const tasksCompletedFilter = rangeFilter("completed_at", { gte: timestamp60DaysAgo.from })
    const tasksFilteredObjectSet = filteredObjectSet(tasksCompletedFilter, baseObjectSet(`${objectTypePrefix}${objectIdTask}`))
    const taskSearchAroundSet = searchAroundObjectSet({ objectSet: tasksFilteredObjectSet, relationSide: "TARGET", relationId: `${objectTypePrefix}${relationIdTaskMatter}` })

    const dormantMattersObjectSet = subtractedObjectSet([openMatters, taskSearchAroundSet])
    matterObjectSets.push(dormantMattersObjectSet)
}

