const escapeHtml = (s = '') =>
  String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;')

const notificationType = (messageType) => {
  switch(messageType) {
    case "Case Evaluation Drafted": return 'Evaluation Drafted'
    case "Case Evaluation Submitted": return 'Evaluation Submitted'
    case "Case Evaluation Supplemented": return 'Evaluation Supplemented'
    case "Case Evaluation Decision Rejected": return 'Evaluation Rejected'
    case "Case Evaluation Decision Approved": return 'Evaluation Approved'
    case "Case Evaluation Decision Re-routed": return 'Evaluation Re-routed'
    case "Case Evaluation Reassigned": return 'Evaluation Reassigned'
    default: return false;
  }
}

const notificationTagClass = (messageType) => {
  switch(messageType) {
    case "Case Evaluation Drafted":
    case "Case Evaluation Supplemented":
      return 'bp5-tag bp5-round'
    case "Case Evaluation Submitted":
      return 'bp5-tag bp5-round bp5-intent-primary'
    case "Case Evaluation Decision Rejected":
      return 'bp5-tag bp5-round bp5-intent-danger'
    case "Case Evaluation Decision Approved":
      return 'bp5-tag bp5-round bp5-intent-success'
    case "Case Evaluation Decision Re-routed":
    case "Case Evaluation Reassigned":
      return 'bp5-tag bp5-round bp5-intent-warning'
    default:
      return '';
  }
}
const notificationTextBorderIntent = (messageType) => {
  switch(messageType) {
    case "Case Evaluation Submitted": return 'bp5-intent-primary'
    case "Case Evaluation Decision Rejected": return 'bp5-intent-danger'
    case "Case Evaluation Decision Approved": return 'bp5-intent-success'
