}

const messageSenders = Array.isArray({{ff_get_case_evaluation_messages.sent_by_details}})
  ? {{ff_get_case_evaluation_messages.sent_by_details}}
  : [];

// Robust person lookup (by id/email; fallback derive from email like f_format_matter_comments)
const getPersonInfo = (personId) => {
  if (!personId || String(personId).toLowerCase() === 'system') {
    return { person_name: 'System Admin', company_name: 'Hence', email: null, id: 'system' }
  }
  const key = String(personId).toLowerCase()
  const hit = messageSenders.find(p => {
    const pid = p?.id ? String(p.id).toLowerCase() : null
    const pem = p?.email ? String(p.email).toLowerCase() : null
    return pid === key || pem === key
  })
  if (hit) return hit

  const [local, domain] = key.split('@')
  const prettyLocal = (local || key).replace(/[._-]+/g, ' ').replace(/\b\w/g, c => c.toUpperCase())
  const prettyDomain = (domain || '').toLowerCase()
  return { person_name: prettyLocal, company_name: prettyDomain, email: key, id: key }
}

let previousSender = null;
let previousDay = null;
let isPreviousMessageNotification = false

const formatMessageBody = (messageContent, messageType) => {
  switch(messageType) {
    case "Case Evaluation Decision Re-routed": {
      const idNameRegex = /<@(.+)\|(.+)>/;
      const idNameMatch = (messageContent || '').match(idNameRegex);
      const id = idNameMatch?.at(1) ?? 'Error: Id not retrieved';
      const name = idNameMatch?.at(2) ?? 'Error: Name not retrieved';

      const content = (messageContent || '').replace(idNameRegex, '').trim();

      return `<span id="${escapeHtml(id)}" class="bp5-text-small bp5-text-muted">To: ${escapeHtml(name)}</span><br/><br/><span>${content}</span>`
    }
    default:
      // Preserve existing behavior (no HTML escaping) to avoid breaking formatting users may rely on
      return messageContent ?? '';
  }
}

const formatInlineTaggedPeople = (personIds) => {
  const ids = Array.isArray(personIds) ? personIds.filter(Boolean) : []
  if (!ids.length) return ''

  const people = ids.map(pid => getPersonInfo(pid))
  const first = people[0]
  const firstName = first?.person_name || ids[0]
  const restCount = Math.max(people.length - 1, 0)

  const titleLines = people.map(p => {
    const name = p?.person_name || ''
    const comp = (p?.company_name || '').trim()
    return comp ? `${name} — ${comp}` : name
  })
  const titleAttr = ` title="${escapeHtml(titleLines.join('\n')).replace(/\n/g, '&#10;')}"`

  const label = restCount > 0 ? `@${firstName} + ${restCount}` : `@${firstName}`

  return `<span class="bubble-tags bubble-tags--block"><span class="tagged-summary-chip"${titleAttr}>${escapeHtml(label)}</span></span>`
}

