content = `<div class="comment-list-container">
  ${messages.map(message => {
    const systemNotificationType = notificationType(message.messageType)
    const systemNotificationIntent = notificationTagClass(message.messageType)
    const isCurrentMessageNotification = Boolean(systemNotificationIntent)

    if (!systemNotificationType) {
      commentCount++;
    }

    const senderInfo = getPersonInfo(message.sentBy)
    const sameSender = (previousSender === message.sentBy) && !isPreviousMessageNotification && !isCurrentMessageNotification
    previousSender = message.sentBy
    isPreviousMessageNotification = isCurrentMessageNotification

    const formatDay = moment(message.sentAt).format('LL')
    const sameDay = previousDay === formatDay 
    previousDay = formatDay

    const tagsHtml = formatInlineTaggedPeople(message?.taggedPeople)
    const textHtml = (formatMessageBody(message.messageBody, message.messageType) || '').trim()
    const bubbleInner = tagsHtml ? `${textHtml}${tagsHtml}` : textHtml

    const senderCompanyTitle = (senderInfo?.company_name || '').trim()
      ? ` title="${escapeHtml(senderInfo.company_name.trim())}"`
      : ''

    return `
      ${sameDay ? '' : `<hr class="timeline-separator"><div class="chat-date bp5-text-small"><span>${formatDay}</span></div>`}
      <div id="cmt-${message.sentAt}" class="comment-item ${(currentUserId === message.sentBy) && !systemNotificationType ? 'current-user-comment' : ''} ${systemNotificationType ? 'system bp5-callout' : ''}">
        ${sameSender && sameDay ? '' : `
