const isNotEmpty = (value) => value && value.length > 0

function addExactMatchFilters(exactMatchfilters) {
  exactMatchfilters.forEach(filter => {
    if (isNotEmpty(filter.values)) {
      filters.push(exactMatchFilter(filter.values, filter.property))
    }
  })
}

function addBooleanFilters(booleanFilters) {
  booleanFilters.forEach(filter => {
    if (isNotEmpty(filter.values)) {
      if (filter.values.includes(null)) {
        const notNullValues = filter.values.filter(value => value !== null)
        const currentFilters = []

        if (isNotEmpty(notNullValues)) {
          currentFilters.push(exactMatchFilter(notNullValues, filter.property))
        }

        currentFilters.push(notFilter(hasPropertyFilter(filter.property)))
        filters.push(orFilter(currentFilters))
      } else {
        filters.push(exactMatchFilter(filter.values, filter.property))
      }
    }
  })
}

function addDateRangeFilters(ranges) {
  ranges.forEach(range => {
    if (isNotEmpty(range.from) && isNotEmpty(range.to)) {
      filters.push(rangeFilter(range.field, { lte: range.to, gte: range.from }))
    }
  })
}


