    { values: assignedFirms, property: "assigned_firm" },
    { values: submittedBy, property: "submitted_by" },
    { values: decidedBy, property: "decided_by" },
    { values: evaluationStatuses, property: "status" },
    { values: internalProcessing, property: "internal_processing"}
  ]

  const dateRangesFilters = [
    { from: approvedDateFrom, to: approvedDateTo, field: "decided_on" },
	{ from: approvedOnFrom,    to: approvedOnTo,    field: "decided_on" },
    { from: submittedDateFrom, to: submittedDateTo, field: "submitted_on" }
  ]

  addExactMatchFilters(exactMatchFilters)
  addBooleanFilters(booleanFilters)
  addDateRangeFilters(dateRangesFilters)

  // if the user has supplied an approved-on date range, only show actual “Approved” decisions
  if ((approvedOnFrom || approvedOnTo)) {
	  filters.push(exactMatchFilter(["Approved"], "decision"))
  }

  if (isNotEmpty(caseNumbers)) {
    addCaseNumberFilters(caseNumbers)
  }

  if (isNotEmpty(opposingFirms)) {
    addOpposingFirmFilters(opposingFirms)
  }

  if (isNotEmpty(caseNames)) {
    addCaseNameFilters(caseNames)
  }

  if (isNotEmpty(assignedApprovers)) {
    addAssignedApproverFilters(assignedApprovers)
  }
}

