const dateDifferenceSimple = (date) => {
  if (!date) {
    return null
  }
  const previousDate = moment(date)
  const currentDate = moment()

  const years = currentDate.diff(previousDate, 'years')
  previousDate.add(years, 'years')
  const months = currentDate.diff(previousDate, 'months')
  previousDate.add(months, 'months')
  const days = currentDate.diff(previousDate, 'days')
  return `${years}y ${months}m ${days}d`
}

const caseAges = (openDates) => {
  return (openDates || []).map((date) => {
    return dateDifferenceSimple(date) 
  })
}

const formatDates = (dates) => {
  return (dates || []).map((date) => {
    return date ? moment(date).format(): null
  })
}

const percentProgress = (progressValues) => {
  return (progressValues || []).map((progress) => {
    return progress ? Math.round(progress * 100) : 0
  })
}

const getPeopleNamesById = (peopleArray, idsArray) => {
  return (idsArray || []).map(id => {
      const person = (peopleArray || []).find(p => p.id === id)
      return person ? person.full_name : null
  })
}

const getFirmsByMatter = (matterData, matterIds = []) => {
    let result = {
        "Defending Firm": [],
        "Discovery Counsel": [],
        "Early Starter Firm": []
    }
    function extractFirmNames(matterData, matterId, firmType) {
      return matterData[matterId]?.byType[firmType]?.map(firm => firm.name).join("")
    }

    matterIds.forEach(matterId => {
        const canSeeAllFirms = matterData[matterId]?.byType["Defending Firm"]?.some(firm => firm.id === currentfirmId) || isInternatUser

        result["Defending Firm"].push(canSeeAllFirms ? extractFirmNames(matterData, matterId, "Defending Firm") : null)
        result["Discovery Counsel"].push(canSeeAllFirms ? extractFirmNames(matterData, matterId, "Discovery Counsel") : null)
        result["Early Starter Firm"].push(extractFirmNames(matterData, matterId, "Early Starter Firm") ?? null)
    })

    return result
}

const formatPrimaryAssignee = (matterData, assignmentData, matterIds) => {
  return (matterIds || []).map(matterId => {
    const canSeeAllFirms = matterData[matterId]?.byType["Defending Firm"]?.some(firm => firm.id === currentfirmId) || isInternatUser
    if (canSeeAllFirms && assignmentData.hasOwnProperty(matterId) && assignmentData[matterId].length > 0) {
        return (assignmentData[matterId] || []).map(item => `${item.pocName} - (${item.firmName})`)
    } else {
