function addExactMatchFilters(exactMatchfilters) {
  exactMatchfilters.forEach(filter => {
    if (isNotEmpty(filter.values)) {
      filters.push(exactMatchFilter(filter.values, filter.property))
    }
  })
}

function addBooleanFilters(booleanFilters) {
  booleanFilters.forEach(filter => {
    if (isNotEmpty(filter.values)) {
      if (filter.values.includes(null)) {
        const notNullValues = filter.values.filter(value => value !== null)
        const currentFilters = []

        if (isNotEmpty(notNullValues)) {
          currentFilters.push(exactMatchFilter(notNullValues, filter.property))
        }

        currentFilters.push(notFilter(hasPropertyFilter(filter.property)))
        filters.push(orFilter(currentFilters))
      } else {
        filters.push(exactMatchFilter(filter.values, filter.property))
      }
    }
  })
}

function addDateRangeFilters(ranges) {
  ranges.forEach(range => {
    if (isNotEmpty(range.from) && isNotEmpty(range.to)) {
      filters.push(rangeFilter(range.field, { lte: range.to, gte: range.from }))
    }
  })
}

function addNumberRangeFilters(ranges) {
  ranges.forEach(range => {
    if (!isNaN(range.from) || !isNaN(range.to)) {
      filters.push(rangeNumberFilter(range.field, { gte: range.from, lte: range.to }))
    }
  })
}

function addMatterTagsFilter(options) {
  const uniqueOptions = [...new Set(options ?? [])];
  if (!uniqueOptions || !uniqueOptions.length) {
    return;
  }
  const orFilters = [];
  uniqueOptions.forEach(tagOption => {
    if (tagOption === "Case Evaluation Has Been Released") {
      orFilters.push(hasPropertyFilter("evaluation_released_at"));
    }
    if (tagOption === "Has Matter Disposition") {
      orFilters.push(hasPropertyFilter("matter_disposition_updated_at"));
    }
    if (tagOption === "Has Disposition Summary") {
      orFilters.push(hasPropertyFilter("final_disposition_completed_at"));
    }
    if (tagOption === "Has MCR Outcome switched to Trial Candidate") {
      orFilters.push(exactMatchFilter([true], "mcr_outcome_switched_to_trial_by_oc"));
    }
    // CA-lawsuit tag: both flags true
    if (tagOption === "Claims Turned To Lawsuit") {
      orFilters.push(andFilter([
        exactMatchFilter([true], "ca_civil_penalty_notice_flag"),
        exactMatchFilter([true], "ca_lawsuit_flag")
      ]));
    }
  });
  filters.push(orFilter(orFilters));
}

