    { from: trialDateFrom, to: trialDateTo, field: "trial_date" },
    { from: serveDateFrom, to: serveDateTo, field: "serve_notice_date" },
    { from: offerServeDateFrom, to: offerServeDateTo, field: "offer_998_serve_date" },
    { from: preLitDemandFrom, to: preLitDemandTo, field: "pre_lit_demand_date" },
    { from: {{f_calculate_case_age_filter_value.from}}, to: {{f_calculate_case_age_filter_value.to}}, field: "serve_notice_date" },
    { from: mcrDateFrom, to: mcrDateTo, field: "mcr_date" },
    { from: mcrCompletionDateFrom, to: mcrCompletionDateTo, field: "mcr_completion_date" },
  ]

  const numberRangesFilters = [
    { from: parseFloat(actualSpendMin), to: parseFloat(actualSpendMax), field: "total_spend" }
  ]

  addExactMatchFilters(exactMatchFilters)
  addBooleanFilters(booleanFilters)
  addDateRangeFilters(dateRangesFilters)
  addNumberRangeFilters(numberRangesFilters)

  if (isNotEmpty(outsideCounsel)) {
    addOutsideCounselFilters(outsideCounsel, isExternalUserLoadingFirmAssignment)
  }

  if (isNotEmpty(matterTags)) {
    addMatterTagsFilter(matterTags)
  }

  if (isNotEmpty(opposingFirms)) {
    addOpposingFirmFilters(opposingFirms)
  }

  if (isNotEmpty(primaryAssignees)) {
    addPrimaryAssigneeFilters(primaryAssignees)
  }

  if (mcrCompleted?.length == 1) {
    if (mcrCompleted?.includes(true)) {
      filters.push(exactMatchFilter(["Completed"], "mcr_status"))
    } else if (mcrCompleted?.includes(false)) {
      filters.push(notFilter(exactMatchFilter(["Completed"], "mcr_status")))
    }
  }
}

function addPreFilters() {
  switch (preFilterSelected) {
    case "upcoming_trials":
      addUpcomingTrialsFilters()
      break
    case "pre_lit_cases":
      addPreLitCasesFilters()
      break
    case "dormant_cases":
      addDormantCasesFilters()
      break
    case "cases_pending_mcr":
      addCasesPendingMCRFilters()
      break
  }
}

/** Ensure external users can see CA-lawsuit matters, but keep Unassigned hidden */
function caLawsuitObjectSetForExternals() {
  return filteredObjectSet(
    andFilter([
      exactMatchFilter([true], "ca_civil_penalty_notice_flag"),
      exactMatchFilter([true], "ca_lawsuit_flag"),
      notFilter(exactMatchFilter(["Unassigned"], "assignment_status"))
    ]),
    baseObjectSet(`${objectTypePrefix}${objectIdMatter}`)
  );
}

/** External firm visibility (mirror of visibleMatters):
 *  external users only see matters assigned to their firm (exclude "unsigned" matters)
 */
function externalFirmAssignedMattersObjectSet() {
  if (!currentUserFirmId) {
    return null;
  }

  // Start from the current user's firm
  const firmObjectSet = filteredObjectSet(
    exactMatchFilter([currentUserFirmId], "id"),
    baseObjectSet(`${objectTypePrefix}${objectIdFirm}`)
  );

  // Firm -> Matter Assignment
  const assignmentObjectSet = searchAroundObjectSet({
    objectSet: firmObjectSet,
    relationSide: "SOURCE",
    relationId: `${objectTypePrefix}${relationIdMatterAssignmentCompany}`
  });

  // Matter Assignment -> Matter
  return searchAroundObjectSet({
    objectSet: assignmentObjectSet,
    relationSide: "TARGET",
    relationId: `${objectTypePrefix}${relationIdMatterAssignmentMatter}`
  });
}

// Main Query building function
function buildQuery() {
  let objectSet = isNotEmpty(matterObjectSets)
    ? intersectedObjectSet(matterObjectSets)
    : baseObjectSet(`${objectTypePrefix}${objectIdMatter}`)

  // Ensure externals can see CA-lawsuit matters; keep Unassigned hidden
  if (isUserFromExternalLawFirm) {
    objectSet = unionedObjectSet([objectSet, caLawsuitObjectSetForExternals()]);
  }

  // Apply same visibility rule as f_display_all_matters.visibleMatters:
  // external users only see matters assigned to their firm (exclude "unsigned" matters)
  if (isUserFromExternalLawFirm && currentUserFirmId) {
    const externalFirmMatters = externalFirmAssignedMattersObjectSet();
    if (externalFirmMatters) {
      objectSet = intersectedObjectSet([objectSet, externalFirmMatters]);
    }
  }

  sortOrderQueue.push({
    singleObjectTypeProperty: {
      propertyTypeRid: defaultPropertyId || {{f_ontology_props_matter.ridMap.last_modified}},
      order: defaultSortOrder || 'DESCENDING'
    },
    type: "singleObjectTypeProperty"
  })

  return {
    objectSet: filteredObjectSet(andFilter(filters), objectSet),
    objectSetContext: {},
    pageSize: {{v_matter_table_limit}},
    propertySet: propertySet(),
    resultOrdering: {
      propertyValue: {
        propertyOrdering: sortOrderQueue
      },
      type: "propertyValue"
    }
  }
}

// Execute functions to construct the query
addSearchFilters()
addFiltersFromFiltersObject()
addPreFilters()

return buildQuery()

