// --- Identify "stage added" system comments robustly ---
const isStageAddedSystemComment = (msg) => {
  const sysCode = String(
    msg?.system_comment_code ?? msg?.systemCommentCode ?? ''
  ).toUpperCase();

  if (sysCode === 'STAGE_ADDED') return true;

  // Heuristic for legacy payloads (no explicit code)
  const mt = String(msg?.messageType ?? '').toLowerCase();
  const body = String(msg?.messageBody ?? '').toLowerCase();

  const mentionsStage = /\bstage(s)?\b/.test(mt) || /\bstage(s)?\b/.test(body);
  const mentionsAdded = /\badded|created|inserted|added to\b/.test(mt) || /\badded|created|inserted|added to\b/.test(body);
  const systemish = isSystemSender(msg?.sentBy) || String(msg?.messageType || '').toLowerCase() !== 'matter comment';

  return Boolean(systemish && mentionsStage && mentionsAdded);
};

const notificationType = (messageType) => {
  switch(messageType) {
    case "Matter Imported": return 'Matter Imported';
    case "Matter Assigned": return 'Matter Assigned';
    case "Matter Reassigned": return 'Matter Reassigned';
    case "Matter Settled": return 'Matter Settled';
    case "Matter Closed": return 'Matter Closed';
    case "Matter Status Reverted": return 'Status Reverted';
    case "Matter Primary Assignee Added": return 'Primary Assignee Added';
    case "Matter Matter Disposition Submitted": return 'Matter Disposition Submitted';
    case "Matter MCR Submitted": return 'Midpoint Case Review Submitted';
    case "Matter MCR Completed": return 'Midpoint Case Review Completed';
    case "Matter MCR Not Applicable": return 'Midpoint Case Review Not Applicable';
    case "VRS Outcome Reviewed": return 'VRS Outcome Reviewed';
    case "Notice Received Date Changed": return 'Notice Received Date Changed';
    case "Final Buyback Decision": return 'Final Buyback Decision';
    case "Notice Received Date": return 'Notice Received Date Added';
