const formatInlineTaggedPeople = (personIds) => {
  const ids = Array.isArray(personIds) ? personIds.filter(Boolean) : [];
  if (!ids.length) return '';

  const people = ids.map(pid => getPersonInfo(pid));
  const first = people[0];
  const firstName = first?.person_name || ids[0];
  const restCount = Math.max(people.length - 1, 0);

  const titleLines = people.map(p => {
    const name = p?.person_name || '';
    const comp = (p?.company_name || '').trim();
    return comp ? `${name} — ${comp}` : name;
  });
  const titleAttr = ` title="${escapeHtml(titleLines.join('\n')).replace(/\n/g, '&#10;')}"`;

  const label = restCount > 0 ? `@${firstName} + ${restCount}` : `@${firstName}`;

  return `<span class="bubble-tags bubble-tags--block"><span class="tagged-summary-chip"${titleAttr}>${escapeHtml(label)}</span></span>`;
};

