    // Base notification mapping
    let systemNotificationType = notificationType(message.messageType);
    let systemNotificationIntent = notificationTagClass(message.messageType);

    // Detect "Stage Added" system comments
    const stageAdded = isStageAddedSystemComment(message);

    // If it is a "Stage Added" system comment, force it to render as a system callout,
    // with a larger box like other system notices.
    if (stageAdded) {
      if (!systemNotificationType) systemNotificationType = 'Stage Added';
      if (!systemNotificationIntent) systemNotificationIntent = 'bp5-tag bp5-round';
    }

    const isCurrentMessageNotification = Boolean(systemNotificationType || stageAdded);

    // --- increment only for user-authored comments ---
    if (isUserAuthoredComment(message)) commentCount++;

    const senderInfo = getPersonInfo(message?.sentBy);

    const sameSender = (previousSender === message?.sentBy) &&
      !isPreviousMessageNotification && !isCurrentMessageNotification;
    previousSender = message?.sentBy;
    isPreviousMessageNotification = isCurrentMessageNotification;

    const formatDay = moment(message.sentAt).format('LL');
    const sameDay = previousDay === formatDay;
    previousDay = formatDay;

    const tagsHtml = formatInlineTaggedPeople(message?.taggedPeople);
    const senderCompanyTitle = (senderInfo?.company_name || '').trim()
      ? ` title="${escapeHtml(senderInfo.company_name.trim())}"`
      : '';

    const textHtml = formatMessageBody(message.messageBody, message.messageType).trim();
    const bubbleInner = tagsHtml ? `${textHtml}${tagsHtml}` : textHtml;

    // Only style as "current-user-comment" for actual user-authored comments
    const isCurrentUsersUserComment =
      isUserAuthoredComment(message) && (currentUserId === message?.sentBy);

    const bigBoxClass = stageAdded ? ' system-comment-box--lg' : '';

    return `
      ${sameDay ? '' : `<hr class="timeline-separator"><div class="chat-date bp5-text-small"><span>${formatDay}</span></div>`}
      <div id="cmt-${message.sentAt}"
           class="comment-item ${isCurrentUsersUserComment ? 'current-user-comment' : ''} ${(systemNotificationType || stageAdded) ? 'system bp5-callout' : ''}${bigBoxClass}">
        ${sameSender && sameDay ? '' : `
          <div class="sent-by">
            <span${senderCompanyTitle}>${(systemNotificationType || stageAdded) ? '' : escapeHtml(senderInfo?.person_name || '')}</span>
            <span class="bp5-text-muted">
              ${(systemNotificationType || stageAdded) ? '' : '| '}
              <span class="${systemNotificationIntent}">
                ${(systemNotificationType || stageAdded) ? systemNotificationType : escapeHtml(senderInfo?.company_name || '')}
              </span>
