// f_oss_matter_stage_events_dates_unified
// Full pipeline with robust Matter Name resolution using:
// - q_load_matter_objects (ontology-mapped)
// - q_load_matters_intersected (via f_map_matters_id_to_name_from_intersected)
// - inline fallbacks from rows/events/assignments

// ==============================
// Utilities
// ==============================
const toKey = v => (v == null ? null : String(v));
const isValidYMD = s => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s.trim());
const toYMD = s => {
  if (!s) return null;
  const m = String(s).match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? `${m[1]}-${m[2]}-${m[3]}` : null;
};
function extractEventDef(dateDef) {
  const s = String(dateDef || '');
  if (!s) return null;
  const m = s.match(/^([A-Za-z0-9_-]+?E[0-9]+)(?:D.+)?$/);
  return m ? m[1] : (s.includes('D') ? s.split('D')[0] : null);
}
function pickName(obj) {
  if (!obj || typeof obj !== 'object') return null;
  const fields = [
    'title','name','matter_name','matter_title','display_name',
    'display_label','short_title','case_name','case_title',
    'caption','label','text','__title'
  ];
  for (const f of fields) {
    const v = obj?.[f];
    if (typeof v === 'string' && v.trim()) return v.trim();
  }
  return null;
}
function pickDeepName(x) {
  return (
    pickName(x) ||
    pickName(x?.matter) ||
    pickName(Array.isArray(x?.matter) ? x.matter[0] : null) ||
    pickName(x?.data) ||
    pickName(x?.attributes) ||
    null
  );
}

// ==============================
// Load & map DATES
// ==============================
const r = {{q_fetch_matter_stage_event_dates_unified.result}} ?? [];
const rawDateResults = Array.isArray(r) ? (r[0]?.results ?? []) : (r?.results ?? []);
const dateRows = mapResultsToValueOnly(rawDateResults, {{f_ontology_props_date_live.propertyMap}}) ?? [];

// ==============================
// Load & map EVENTS (aligned scope)
// ==============================
const re = {{q_fetch_events_unified.result}} ?? [];
const rawEventResults = Array.isArray(re) ? (re[0]?.results ?? []) : (re?.results ?? []);
const evAll0 = mapResultsToValueOnly(rawEventResults, {{f_ontology_props_event_live.propertyMap}}) ?? [];

// De-dupe events by id
const evSeen = new Set();
const allEvents = [];
for (const e of evAll0) {
  if (!e || !e.id || evSeen.has(e.id)) continue;
  evSeen.add(e.id);
  allEvents.push(e);
}

// Indexes for joins
const byId = Object.create(null);
const byDef = Object.create(null);
const byStageDef = Object.create(null);
for (const e of allEvents) {
  byId[e.id] = e;
  const edef = e.event_stage_definition_id || e.event_definition_id || null;
  if (edef) {
    (byDef[edef] ||= []).push(e);
    if (e.stage_live_id) byStageDef[`${e.stage_live_id}::${edef}`] = e;
  }
}

// ==============================
// Enrich dates with best-matching event
// ==============================
const enriched = dateRows.map(d => {
  let ev = null;

  // 1) direct link by event_live_id
  if (d?.event_live_id && byId[d.event_live_id]) ev = byId[d.event_live_id];

  // 2) definition-based match (prefer same stage, then same matter)
  if (!ev) {
    const edef = extractEventDef(d?.date_event_definition_id);
    if (edef) {
      if (d?.stage_live_id && byStageDef[`${d.stage_live_id}::${edef}`]) {
        ev = byStageDef[`${d.stage_live_id}::${edef}`];
      } else if (byDef[edef]?.length) {
        ev = byDef[edef].find(x => !d?.matter_id || x.matter_id === d.matter_id) || byDef[edef][0];
      }
    }
  }

  return {
    ...d,
    event: ev ?? null,
    event_name: ev?.event_name ?? ev?.name ?? d?.event_name ?? null,
    event_stage_definition_id: ev?.event_stage_definition_id ?? null,
    event_stage_live_id: ev?.stage_live_id ?? null
  };
});

// ==============================
// Normalize & de-dupe date rows
// ==============================
const cleaned = [];
const seenKey = new Set();

for (const row of enriched) {
  const ymd = toYMD(row?.date);
  const hasValidDate = !!ymd && isValidYMD(ymd);
  const eventId = row?.event_live_id || row?.event?.id || null;
  const matterId = row?.matter_id || row?.event?.matter_id || null;

  if (!hasValidDate) continue;
  if (!eventId) continue;
  if (!matterId) continue;

  const key = `${row?.id || `${matterId}:${ymd}`}::${eventId}`;
  if (seenKey.has(key)) continue;
  seenKey.add(key);

  cleaned.push({
    ...row,
    matter_id: matterId,
    event_live_id: eventId,
    date: ymd,
    event_name: row?.event_name ?? null
  });
}

// Distinct matter ids in current scope
const scopeMatterIds = new Set();
for (const s of dateRows)  if (s?.matter_id != null) scopeMatterIds.add(toKey(s.matter_id));
for (const s of allEvents) if (s?.matter_id != null) scopeMatterIds.add(toKey(s.matter_id));
for (const s of cleaned)   if (s?.matter_id != null) scopeMatterIds.add(toKey(s.matter_id));

// ==============================
// Defending Firm resolution
// ==============================
const assignmentMap = {{f_matters_related_assignments_grouped_by_matter}} ?? {};

const dfFromAssignments = Object.create(null);
for (const [matterIdRaw, group] of Object.entries(assignmentMap || {})) {
  const matterId = toKey(matterIdRaw);
  const byFirm = group?.byFirm || {};
  const firms = [];
  for (const [firmId, data] of Object.entries(byFirm)) {
    const roles = data?.roles || [];
    const isDf = roles.some(r => r?.assignmentType === "Defending Firm");
    if (isDf) {
      firms.push({
        id: data?.id || firmId,
        name: data?.name ?? null,
        primaryAssignee: data?.primaryAssignee ?? null,
        assignmentId: data?.assignmentId ?? null
      });
    }
  }
  if (firms.length) dfFromAssignments[matterId] = firms;
}

// ==============================
// Matter objects + map (baseline)
// ==============================
const qm = {{q_load_matter_objects.result}} ?? [];
const matterRaw = Array.isArray(qm) ? (qm[0]?.results ?? []) : (qm?.results ?? []);
const matterRows = mapResultsToValueOnly(matterRaw, {{f_ontology_props_matter.propertyMap}}) ?? [];

const dfFromMatterProps = Object.create(null);
const matterById = Object.create(null);

for (const m of matterRows) {
  if (!m || !m.id) continue;
  const mid = toKey(m.id);
  matterById[mid] = m;

  const ids = Array.isArray(m.defending_firm_ids)
    ? m.defending_firm_ids
    : (m.defending_firms_ids ? m.defending_firms_ids
      : (m.defending_firm_id ? [m.defending_firm_id] : []));
  if (ids?.length) {
    dfFromMatterProps[mid] = ids.map(id => ({ id, name: null }));
  }
}

// ==============================
// NEW: Names from intersected query (preferred for coverage)
// ==============================
const namesById =
  ({{f_map_matters_id_to_name_from_intersected}} ?? {}) ||
  {};

for (const [mid, nm] of Object.entries(namesById)) {
  const k = toKey(mid);
  const name = (typeof nm === 'string' && nm.trim()) ? nm.trim() : null;
  if (!k || !name) continue;
  if (!matterById[k]) matterById[k] = { id: k };
  matterById[k].title        = matterById[k].title        ?? name;
  matterById[k].name         = matterById[k].name         ?? name;
  matterById[k].matter_name  = matterById[k].matter_name  ?? name;
  matterById[k].matter_title = matterById[k].matter_title ?? name;
}

// ==============================
// Backfill: infer names from date/event/assignments when present
// ==============================
const matterNameFromRows = Object.create(null);

// from date rows
for (const s of (dateRows || [])) {
  const mid = toKey(s?.matter_id);
  const nm = pickDeepName(s);
  if (mid && nm && !matterNameFromRows[mid]) matterNameFromRows[mid] = nm;
}
// from events
for (const s of (allEvents || [])) {
  const mid = toKey(s?.matter_id ?? s?.event?.matter_id);
  const nm = pickDeepName(s);
  if (mid && nm && !matterNameFromRows[mid]) matterNameFromRows[mid] = nm;
}
// from assignments container (if any human-readable fields exist)
for (const [mid0, group] of Object.entries(assignmentMap || {})) {
  const mid = toKey(mid0);
  const nm = pickDeepName(group) || group?.matterName || group?.title || null;
  if (mid && nm && !matterNameFromRows[mid]) matterNameFromRows[mid] = nm;
