/**
 * Transforms a column-oriented schema (as returned by queries) into a row-oriented schema (often for use in an {{#each}} loop)
 *
 * Before:
 * {
 *   foo : [1, 2, 3],
 *   bar : [4, 5, 6],
 *   baz : [7, 8, 9]
 * }
 *
 * After:
 * [
 *   { foo : 1, bar : 4, baz : 7 },
 *   { foo : 2, bar : 5, baz : 8 },
 *   { foo : 3, bar : 6, baz : 9 }
 * ]
 */

function transformColumnSchemaToRowSchema(data) {
  var keys   = _.keys(data);
  var arrays = _.values(data);

  // if `data` comes directly from a SQL query, remove the `._response` property
  // delete data._response;

  var arrayOfPropertyLists = _.zip.apply(_, arrays);

  var arrayOfObjects = _.map(arrayOfPropertyLists, function(list) {
    var obj = {};

    _.each(keys, function(key, i) {
      obj[key] = list[i];
    });

    return obj;
  });

  return arrayOfObjects;
}

/**
 * Transforms a row-oriented schema into a column-oriented schema (as returned by queries).
 * Note: The first object of the array needs to contain all keys to be extracted (future columns).
 * If the first object does not contain a superset of all keys, you can use the alternative commented code in the function.
 *
 * Before:
 * [
 *   { foo : 1, bar : 4, baz : 7 },
 *   { bar : 5, baz : 8, foo : 2 },
 *   { foo : 3, baz : 9, bar : 6 }
 * ]
 *
 * After:
 * {
 *   foo : [1, 2, 3],
 *   bar : [4, 5, 6],
 *   baz : [7, 8, 9]
 * }
 *
 */
function transformRowSchemaToColumnSchema(arr, first_object_has_all_keys=true) {
  if (_.isEmpty(arr)) {
    return [];
  }

  var orderedKeys;
  if(first_object_has_all_keys){
    // In case the first object has all keys
    orderedKeys = _.chain(arr)
        .first()
        .keys()
        .sortBy()
        .value();
  } else {
    // Alternative if not all objects have all keys : 
    orderedKeys = _.uniq(_.flatMap(arr, _.keys))
  }

  var sortKeysBy = function(obj) {
    return _.zipObject(orderedKeys, _.map(orderedKeys, function(key) {
      return obj[key];
    }));
  };

  var indexToKeyMapping = _.reduce(orderedKeys, function(agg, key, i) {
    agg[i] = key;
    return agg;
  }, {});

  var arrayOfRowObjects    = _.map(arr, sortKeysBy);
  var arrayOfRowArrays     = _.map(arrayOfRowObjects, function(obj) { return _.values(obj) });
  var arrayOfColumnArrays  = _.unzip(arrayOfRowArrays);
  var objectOfColumnArrays = _.reduce(arrayOfColumnArrays, function(agg, columnArr, i) {
    var key = indexToKeyMapping[i];
    agg[key] = columnArr;
    return agg;
  }, {});

  return objectOfColumnArrays;
}

function transformPhonographObjectSchemaToRowSchema(rawQuery) {
	const parsedData = {}
	const entries = rawQuery.result[0].hits || [];
	const rawData = entries.map(h => h['object']);
	const primaryKeys = Object.keys(rawData[0].primaryKey);
	const propertyMap = {}
	rawData.forEach(obj => Object.keys(obj.properties).forEach(prop => {propertyMap[prop] = 1}))
	const properties = Object.keys(propertyMap);

	for (const pkey of primaryKeys) {
		parsedData[pkey] = []
	}
	for (const prop of properties) {
		parsedData[prop] = []
	}
	for (const obj of rawData) {
		for (const pkey of primaryKeys) {
			parsedData[pkey].push(obj.primaryKey[pkey])
		}
		for (const prop of properties) {
			parsedData[prop].push(obj.properties[prop])
		}
	}

	return parsedData;
}

/**
 * Sort OSV2 data by the rid order from the origin query
 * 
 * data: List of objects from load query
 * rids: List of string rids from sort query
 */ 
function sortDataByRids(data, rids) {
  return rids.map(rid => data.find(obj => obj.objectRid === rid))
}

/**
 * Processes a single entry from result.[0].objectTypes returned from /ontology/ontology/bulkLoadEntities
 * 
 * returns an object with:
 * - meta info about the object type
 * - property rid map to get details about each property
 * - property id map to lookup property rid by id
 */
function getObjectTypeMetadata(objectTypesWrapper) {
  if (!objectTypesWrapper) {
    return null
  }
  const objectType = objectTypesWrapper.objectType

  const meta = {
    id: objectType.id,
    rid: objectType.rid,
    apiName: objectType.apiName,
    status: objectType.status.type,
    description: objectType.displayMetadata.description,
    displayNameSingular: objectType.displayMetadata.displayName,
    displayNamePlural: objectType.displayMetadata.pluralDisplayName,
    primaryKeyRid: objectType.primaryKeys[0] ?? null,
    titlePropertyTypeRid: objectType.titlePropertyTypeRid,
    bpIconLocator: objectType.displayMetadata.icon.type === "blueprint" ? objectType.displayMetadata.icon.blueprint.locator : null,
  }

  const ridMap = {}
  const propertyMap = {}
  const propertyData = objectType.propertyTypes
  Object.keys(propertyData).forEach(key => {
    ridMap[propertyData[key].id] = key
    propertyMap[key] = {
      id: propertyData[key].id,
      displayName: propertyData[key].displayMetadata.displayName,
      visibility: propertyData[key].displayMetadata.visibility,
      type: propertyData[key].type.type,
      subType: propertyData[key].type.array?.subtype.type,
      status: propertyData[key].status.type,
      isSortable: propertyData[key].typeClasses.some(cls => cls.name === "SORTABLE")
    }
  })

  return {
    "meta": meta,
    "ridMap": ridMap,
    "propertyMap": propertyMap,
  }
}

/**
 * Turn results of objects into a mapped content instead of rid map
 */
function mapResultsToReadableContent(objectList, objectPropertyMap) {
  if (!objectList || !objectPropertyMap) {
    return []
  }
  return objectList.map(item => {
    const objProperties = {...item.properties, ...item.primaryKey}
    const mappedItem = {}
    Object.keys(objectPropertyMap).forEach(rid => {
      const propertyMeta = objectPropertyMap[rid]
      if (propertyMeta) {
        const propContent = objProperties[rid] || {}
        const objectType = objectPropertyMap[rid].type
        const value = propContent[objectType] ?? null
        mappedItem[propertyMeta.id] = {
          label: propertyMeta.displayName,
          type: objectType === 'array'
            ? (objectPropertyMap[rid].subType + '[]')
            : objectPropertyMap[rid].type,
          value: objectType === 'array'
            ? (value?.map(subitem => subitem[subitem.type]) ?? null)
            : value
        }
      }
    })
    return mappedItem
  })
}

/**
 * Turn results of objects into a mapped content instead of rid map
 */
function mapResultsToValueOnly(objectList, objectPropertyMap) {
  if (!objectList || !objectPropertyMap) {
    return []
  }

  return objectList.map(item => {
    const objProperties = { ...item.properties, ...item.primaryKey }

    return Object.keys(objectPropertyMap)
      .filter(rid => objectPropertyMap[rid])
      .reduce((mappedItem, rid) => {
        const { type, id } = objectPropertyMap[rid]
        const propContent = objProperties[rid] || {}

        if (type === 'array' && Array.isArray(propContent.array)) {
          mappedItem[id] = propContent.array.map(element => element.string || element[type])
        } else {
          mappedItem[id] = propContent[type] ?? null
        }

        return mappedItem
      }, {})
  })
}

const baseObjectSet = (objectTypeId) => ({
  base: {
    objectTypeId
  },
  type: "base"
})

const filteredObjectSet = (filter, objectSet) => ({
  filtered: {
    objectSet,
    filter
  },
  type: "filtered"
})

const intersectedObjectSet = (objectSets = []) => ({
  intersected: {
