  },
  type: "intersected"
})

const subtractedObjectSet = (objectSets = []) => ({
  subtracted: {
    objectSets
  },
  type: "subtracted"
})

const unionedObjectSet = (objectSets = []) => ({
  unioned: {
    objectSets
  },
