const dateDifference = (date) => {
  if (!date) {
    return null
  }
  const previousDate = moment(date)
  const currentDate = moment()

  const years = currentDate.diff(previousDate, 'years')
  previousDate.add(years, 'years')
  const months = currentDate.diff(previousDate, 'months')
  previousDate.add(months, 'months')
  const days = currentDate.diff(previousDate, 'days')

  const displayStrArr = [
    '<span class="bp5-text-disabled">',
    `${years}y`,
    `${months}m`,
    `${days}d`,
  ]
  const insertClosingSpanPos = 
    years === 0 && months === 0 && days === 0 ? 4 :
    years === 0 && months === 0 ? 3 :
    years === 0 ? 2 :
    1 // just closes the span with no change
  
  displayStrArr.splice(insertClosingSpanPos, 0, '</span>')

  return displayStrArr.join(' ')
}


