const outsideCounselDisplay = (
  assignmentDetails,
  separatorRole = ', ',
  separatorFirm = ' ',
  isUserFromExternalLawFirm = false,
  currentUserFirmId = null,
) => {
  if (!assignmentDetails || !assignmentDetails.byFirm || Object.keys(assignmentDetails.byFirm).length === 0) {
    return '-';
  }

  let firmCanSeeAll = !isUserFromExternalLawFirm;

  if (isUserFromExternalLawFirm) {
    const roles = (assignmentDetails.byFirm?.[currentUserFirmId]?.roles || []).map(r => r.assignmentType);
    const isDF  = roles.includes("Defending Firm");
    const isESF = roles.includes("Early Starter Firm");
    // SNF is still treated as "DC-ish" for progress visibility
    const isDC  = roles.includes("Discovery Counsel") || roles.includes("SNF") || roles.includes("Statutory Notice Firm");
    firmCanSeeAll  = isDF || isESF || isDC;
  }

  // Caller hint (e.g., external read-only CA-lawsuit viewer)
  if (assignmentDetails.__forceShowAll === true) {
    firmCanSeeAll = true;
  }

  const byFirm = assignmentDetails.byFirm;
  const firmIds = Object.keys(byFirm);

  // Role priority for ordering firms and role badges
  const ROLE_PRIORITY = new Map([
    ["Defending Firm", 0],
    ["Early Starter Firm", 1],
    ["Discovery Counsel", 2],
    ["Statutory Notice Firm", 3],
    ["SNF", 3], // treat SNF variants after DC
  ]);
  const roleRank = (role) => ROLE_PRIORITY.has(role) ? ROLE_PRIORITY.get(role) : 99;

  const visibleFirmIds = firmIds.filter(fid => {
    const visibleToUser = isUserFromExternalLawFirm
      ? (firmCanSeeAll || fid === String(currentUserFirmId))
      : true;
    if (!visibleToUser) return false;

    const roles = (byFirm[fid]?.roles || []).map(r => r.assignmentType);
    return roles.length > 0; // keep firm if it has any roles (including SNF)
  });

  if (!visibleFirmIds.length) return '-';

  // Build sortable list with best rank per firm (lower = higher priority)
  const sortedFirms = visibleFirmIds
    .map(fid => {
      const firm = byFirm[fid];
      const allRoles = (firm.roles || []).map(r => r.assignmentType);
      const bestRank = Math.min(...allRoles.map(roleRank));
      return {
        fid,
        firm,
        name: firm.name || '',
        roles: allRoles,
        rank: Number.isFinite(bestRank) ? bestRank : 99
      };
    })
    .sort((a, b) => {
      if (a.rank !== b.rank) return a.rank - b.rank;
      return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
    });

  const chunks = sortedFirms.map(({ firm, roles }) => {
    const firmSpend = Object.prototype.hasOwnProperty.call(firm, "firmSpend")
      ? `${formatCurrencyWithSuffix(firm.firmSpend)}`
      : '';


    const superscript = roles
      .slice()
      .sort((r1, r2) => roleRank(r1) - roleRank(r2))
      .map((assignmentType) => {
        const abbr = assignmentType.split(' ').filter(Boolean).map(w => w[0]).join('');
        return `<span title="${assignmentType}">${abbr}</span>`;
      })
      .join(separatorRole);

    return `${firm.name} <sup>&nbsp;<span class="bp5-text-small bp5-text-muted">[${superscript}]</span></sup>`;
  });

  const out = chunks.join(separatorFirm);
  return out && out.trim().length ? out : '-';
}; 

