const manipulateDate = (duration, dimension, operator, format) => {
    const dimensions = ["days", "months", "years"]
    const currentDate = moment()

    if (!duration || isNaN(duration) || !dimensions.includes(dimension.toLowerCase())) {
        return { from: null, to: null }
    }

    let resultDate = currentDate

    if (operator === "subtract") {
        resultDate = resultDate.subtract(duration, dimension.toLowerCase())
    } else if (operator === "add") {
        resultDate = resultDate.add(duration, dimension.toLowerCase())
    } else {
        return { from: null, to: null }
    }

    if (format === "unix") {
        return { from: resultDate.unix() * 1000, to: moment().unix() * 1000 }
    } else if (format === "YYYY-MM-DD") {
        return { from: resultDate.format('YYYY-MM-DD'), to: moment().format('YYYY-MM-DD') }
    } else {
        return { from: null, to: null }
    }
}

