function caseEvaluationAuthorityFormatted({ authority_type, authority, authority_min, authority_max, authority_alphanum }) {
    let formatted;
    switch (authority_type) {
        case "exact":
            formatted = `${formatCurrency(authority)}`;
            break;
        case "range":
            formatted = `${formatCurrency(authority_min)} — ${formatCurrency(authority_max)}`;
            break;
        case "alphanum":
