            break;
    }
    return formatted;
}

function displayEmailContent(emailSet) {
    if (!emailSet || !emailSet.length) {
        return "-"
    }
    const maxDisplayCount = 2;
    let emailString = emailSet
        .slice(0, maxDisplayCount)
        .map((instance) => `<span title="Name: ${instance.personName ? instance.personName : '-'}\nEmail: ${instance.personEmail}">
            ${instance.personName ? instance.personName : instance.personEmail}</span>`
        ).join(", ");

    if (emailSet.length > maxDisplayCount) {
        emailString += ` <span class="more-count" title="${
            emailSet.slice(maxDisplayCount).map((instance) => 
                "- " + (instance.personName ? `${instance.personName} (${instance.personEmail})` : instance.personEmail)
            ).join("\n")
        }">${emailSet.length - maxDisplayCount}&nbsp;more</span>`
    }
    return emailString;
}

/**
 * Process Message Type
 */
function processMessageType(messageBody) {
    if (messageBody?.["type"]) {
        switch (messageBody.type) {
            case "initialized":
                return "LOADED"
            case "beforeUnload":
                return "REMOVED"
            case "userRefresh":
                return "REFRESHED"
        }
    }

    switch (messageBody) {
        case "CLEAR":
        return "CLEAR"
        case "READY":
        return "READY"
        default:
            if (messageBody) {
                return "DATA_RECEIVED"
            }
            else {
                return "UNPROCESSED"
            }
    }

    return "UNKNOWN";
}

/**
 * Is valid render status?
 */
function isValidRenderStatus(status) {
    return status === "CLEAR"
        || status === "READY"
        || status === "DATA_RECEIVED";
}

/**
 * Generate url path
 */
function generatePath(componentRid = "", pageRefresh) {
  if (!componentRid) return null;

  let pageUrl = "";
  if (componentRid.startsWith("ri.slate.main.document")) {
    pageUrl = `/workspace/slate/app/${componentRid}?embedded=true`;
  } else if (componentRid.startsWith("ri.workshop.main.module")) {
    pageUrl = `/workspace/module/view/latest/${componentRid}?embedded=true`;
  }

  if (pageRefresh !== undefined && pageRefresh !== null) {
    pageUrl += `&refresh=${encodeURIComponent(pageRefresh)}`;
  }

  return pageUrl;
}

function displayFormattedText(title = "", raw = "", html = "") {
	if(!raw || !html || !title) return ""
    const charLimit = 380;
    if (html.length <= charLimit) return `<br/>${html}`;

    const truncated = raw.slice(0, charLimit);
    const payload = encodeURIComponent(`${title}||${html}`);

    const seeMore = `<a role="button" tabindex="0" slClickEvent="seeMore" slClickEventValue="${payload}">... see more</a>`;

    return `<br/>${truncated}${seeMore}`;
}

