  display: none;
}

.checkmark {
  position: absolute;
  top: 0;
  left: 0;
  width: 20px;
  height: 20px;
  border: 1px solid;
  border-radius: 3px;
}

sl-app-container .pt-control .pt-control-indicator:before {
  content: "" !important;
  display: none;
}

sl-app-container .pt-control .pt-control-indicator:after,
.checkmark:after {
  content: "";
  position: absolute;
  display: none;
  top: 2px;
  left: 6px;
  width: 6px;
  height: 12px;
  border: solid white;
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}

.customCheckbox .checkbox.checked + .checkmark:after,
.customCheckbox input[type="checkbox"]:checked+.checkmark:after,
sl-app-container input:checked~.pt-control-indicator:after {
  display: block;
