  position: relative;
  margin-top: -15px;
}

.row-header {
  display: table-row;
  position: sticky;
  top: 0;
  z-index: 10;
  height: 30px;

  .column {
    font-size: 16px;

    .customCheckbox {
      bottom: 10px;
    }

    &:hover {
      filter: brightness(110%);

      .table-title {
        opacity: 0.9;
      }
    }
  }

  .table-title {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
  }

  .table-sort-icons {
    display: flex;
    flex-direction: column;

    .bp5-icon-standard {
      opacity: 0.5;
      font-size: 14px;
      width: 12px;
      height: 10px;
      cursor: pointer;
      -webkit-transition: opacity scale .5s;
      -moz-transition: opacity scale .5s;
      transition: opacity scale .5s;

      &:hover {
        -webkit-transform: scale(1.5);
        -moz-transform: scale(1.5);
        transform: scale(1.5);
        opacity: 1;
      }

      &.active {
        opacity: 1;
        transform: scale(1.3);
      }
    }
  }
}

.row {
  display: table-row;
  height: 89px;

  &:hover {
    .column {
      box-shadow: inset 0 0 0 100px rgba(255, 255, 255, 0.05);
    }

    .actions {
      display: block;
    }
  }

  &.disabled .column {
    cursor: not-allowed;
    pointer-events: none !important;
  }
}

.column {
  display: table-cell;
  vertical-align: middle;
  background-color: #17213E;
  padding-top: 10px;
  padding-bottom: 10px;
  padding-left: 20px;
  padding-right: 15px;

  &:first-child {
    border-bottom-left-radius: 5px;
    border-top-left-radius: 5px;
  }

  &:last-child {
    border-top-right-radius: 5px;
    border-bottom-right-radius: 5px;
  }

  .description-container {
    display: -webkit-box; 
    -webkit-box-orient: vertical; 
    -webkit-line-clamp: 2; 
    overflow: hidden; 
    text-overflow: ellipsis; 
  }
}

.matter-table {
  .column:nth-child(1) {
    position: sticky;
    left: 0;
    z-index: 2;
  }

  .column:nth-child(2) {
    position: sticky;
    left: 50px;
    z-index: 1;
  }
}

