// full text hover styles

.hoverable-description {
  display: inline-block;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 250px;

  &:after {
    content: attr(data-full-description);
    position: absolute;
    display: none;
    white-space: normal;
    background-color: #17213E;
    color: #fff;
    padding: 10px;
    text-align: left;
    border: 1px solid #32467D;
    border-radius: 5px;
    z-index: 100;
    width: max-content;
    max-width: 400px;
    /* Adjust max width as needed */
    box-shadow: 0px 8px 16px 0px rgba(0, 0, 0, 0.2);
  }

  &:before {
    border-width: 5px;
    border-style: solid;
    border-color: transparent transparent #32467D transparent;
    bottom: 100%;
    /* Position above the element */
    left: 50%;
    transform: translateX(-50%) translateY(5px);
    /* Adjust translateY to align the arrow */
  }



  &:hover {
    &:after {
      display: block;
    }

    &:before {
      display: block !important;
    }
  }
}


